-- UNN MTH 206 (Advanced Mathematics VI) CBT question bank
-- 598 questions covering: complex-number arithmetic, polar form and
-- De Moivre's theorem, nth roots, exponential/trigonometric/hyperbolic functions
-- of a complex variable, functions of a complex variable, the Cauchy-Riemann
-- equations and harmonic functions, standard number systems, bounded sets
-- (sup/inf), sequences and series of real numbers, differentiation of vectors
-- (tangent vectors, partial differentiation), the gradient/divergence/curl,
-- and integration of vectors (line integrals, potential functions, arc length).
-- All computational answers were verified via sympy, not by hand.
--
-- cbt_questions has no course_code column, so the paper is identified by
-- subject_name. faculty lists every faculty whose course_outlines actually
-- require this course (Physical Sciences, Engineering) so it is not hidden from
-- students outside whichever single faculty happened to author it.

delete from public.cbt_questions where subject_id = 'mth-206-advanced-mathematics-vi';

