  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the complex conjugate $\bar z$ of $z = 2 - i$.', '["$2 + i$", "$-2 - i$", "$-2 + i$", "$2 - i$"]'::jsonb, 0, 'The conjugate reverses the sign of the imaginary part only: $\bar z = 2 + i$.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the complex conjugate $\bar z$ of $z = 3 - i$.', '["$3 + i$", "$-3 - i$", "$-3 + i$", "$3 - i$"]'::jsonb, 0, 'The conjugate reverses the sign of the imaginary part only: $\bar z = 3 + i$.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the complex conjugate $\bar z$ of $z = 2 - 2i$.', '["$2 + 2i$", "$-2 - 2i$", "$-2 + 2i$", "$2 - 2i$"]'::jsonb, 0, 'The conjugate reverses the sign of the imaginary part only: $\bar z = 2 + 2i$.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the complex conjugate $\bar z$ of $z = -3 + 2i$.', '["$-3 - 2i$", "$3 + 2i$", "$3 - 2i$", "$-3 + 2i$"]'::jsonb, 0, 'The conjugate reverses the sign of the imaginary part only: $\bar z = -3 - 2i$.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the complex conjugate $\bar z$ of $z = 1 - 2i$.', '["$1 + 2i$", "$-1 - 2i$", "$-1 + 2i$", "$1 - 2i$"]'::jsonb, 0, 'The conjugate reverses the sign of the imaginary part only: $\bar z = 1 + 2i$.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the complex conjugate $\bar z$ of $z = 4 - 2i$.', '["$4 + 2i$", "$-4 - 2i$", "$-4 + 2i$", "$4 - 2i$"]'::jsonb, 0, 'The conjugate reverses the sign of the imaginary part only: $\bar z = 4 + 2i$.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For any complex number $z = x + iy$, what is $z + \bar z$ equal to?', '["$2x$ (twice the real part)", "$2iy$ (twice the imaginary part)", "$0$", "$2z$"]'::jsonb, 0, '$z + \bar z = (x+iy) + (x-iy) = 2x$, so the sum of a complex number and its conjugate is always real.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For any complex number $z = x + iy$, what is $z - \bar z$ equal to?', '["$2iy$ (twice the imaginary part, as a purely imaginary number)", "$2x$", "$0$", "$2z$"]'::jsonb, 0, '$z - \bar z = (x+iy) - (x-iy) = 2iy$, so the difference is always purely imaginary.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For complex numbers $z_1$ and $z_2$, which identity correctly relates $|z_1 z_2|$ to $|z_1|$ and $|z_2|$?', '["$|z_1 z_2| = |z_1||z_2|$", "$|z_1 z_2| = |z_1| + |z_2|$", "$|z_1 z_2| = |z_1| - |z_2|$", "$|z_1 z_2| = |z_1|^2|z_2|^2$"]'::jsonb, 0, 'The modulus of a product equals the product of the moduli: $|z_1z_2| = |z_1||z_2|$, which follows directly from $z\bar z = |z|^2$ and $(z_1z_2)\overline{(z_1z_2)} = z_1\bar z_1 \, z_2\bar z_2$.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which identity correctly relates the conjugate of a product to the conjugates of its factors?', '["$\\overline{z_1 z_2} = \\bar z_1 \\bar z_2$", "$\\overline{z_1 z_2} = \\bar z_1 + \\bar z_2$", "$\\overline{z_1 z_2} = z_1 z_2$", "$\\overline{z_1 z_2} = \\bar z_1 - \\bar z_2$"]'::jsonb, 0, 'Conjugation distributes over multiplication: $\overline{z_1z_2} = \bar z_1 \bar z_2$, which can be verified directly by expanding both sides with $z_k = x_k+iy_k$.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The set of complex numbers $\mathbb{C}$ can be identified with which geometric structure?', '["The set of ordered pairs $(x, y)$ of real numbers, i.e. the plane $\\mathbb{R}^2$", "The set of positive real numbers only", "A single straight line", "The set of natural numbers only"]'::jsonb, 0, 'Every complex number $z = x+iy$ corresponds to exactly one ordered pair $(x, y)$, so $\mathbb{C}$ is identified with the real plane $\mathbb{R}^2$.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Every real number can be regarded as a complex number. Which of the following explains why?', '["Any real number $x$ can be written as $x + 0i$, i.e. a complex number with zero imaginary part", "Real numbers and complex numbers are entirely unrelated sets", "Only integers can be written as complex numbers", "A complex number is only real when its real part is zero"]'::jsonb, 0, 'Writing $x = x + 0i$ shows every real number is a complex number with imaginary part $0$; the converse is false since not every complex number is real.', 'Complex Number Basics', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Express $z = \sqrt{3} + (1)i$ in polar form $z = r(\cos\theta + i\sin\theta)$, giving $r$ and $\theta$ (with $0 \leq \theta \leq \pi$).', '["$r = 2$, $\\theta = \\frac{\\pi}{6}$", "$r = 3$, $\\theta = \\frac{\\pi}{6}$", "$r = 2$, $\\theta = \\frac{\\pi}{12}$", "$r = 2$, $\\theta = \\frac{\\pi}{3}$"]'::jsonb, 0, '$r = |z| = 2$ and $\theta = \arg z = \frac{\pi}{6}$, since $z = 2(\cos(\frac{\pi}{6}) + i\sin(\frac{\pi}{6}))$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Express $z = 2 \sqrt{2} + (2 \sqrt{2})i$ in polar form $z = r(\cos\theta + i\sin\theta)$, giving $r$ and $\theta$ (with $0 \leq \theta \leq \pi$).', '["$r = 4$, $\\theta = \\frac{\\pi}{4}$", "$r = 5$, $\\theta = \\frac{\\pi}{4}$", "$r = 4$, $\\theta = \\frac{\\pi}{8}$", "$r = 4$, $\\theta = \\frac{\\pi}{2}$"]'::jsonb, 0, '$r = |z| = 4$ and $\theta = \arg z = \frac{\pi}{4}$, since $z = 4(\cos(\frac{\pi}{4}) + i\sin(\frac{\pi}{4}))$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Express $z = 2 + (2 \sqrt{3})i$ in polar form $z = r(\cos\theta + i\sin\theta)$, giving $r$ and $\theta$ (with $0 \leq \theta \leq \pi$).', '["$r = 4$, $\\theta = \\frac{\\pi}{3}$", "$r = 5$, $\\theta = \\frac{\\pi}{3}$", "$r = 4$, $\\theta = \\frac{\\pi}{6}$", "$r = 4$, $\\theta = \\frac{2 \\pi}{3}$"]'::jsonb, 0, '$r = |z| = 4$ and $\theta = \arg z = \frac{\pi}{3}$, since $z = 4(\cos(\frac{\pi}{3}) + i\sin(\frac{\pi}{3}))$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Express $z = 0 + (3)i$ in polar form $z = r(\cos\theta + i\sin\theta)$, giving $r$ and $\theta$ (with $0 \leq \theta \leq \pi$).', '["$r = 3$, $\\theta = \\frac{\\pi}{2}$", "$r = 4$, $\\theta = \\frac{\\pi}{2}$", "$r = 3$, $\\theta = \\frac{\\pi}{4}$", "$r = 3$, $\\theta = \\pi$"]'::jsonb, 0, '$r = |z| = 3$ and $\theta = \arg z = \frac{\pi}{2}$, since $z = 3(\cos(\frac{\pi}{2}) + i\sin(\frac{\pi}{2}))$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Express $z = -2 + (2 \sqrt{3})i$ in polar form $z = r(\cos\theta + i\sin\theta)$, giving $r$ and $\theta$ (with $0 \leq \theta \leq \pi$).', '["$r = 4$, $\\theta = \\frac{2 \\pi}{3}$", "$r = 5$, $\\theta = \\frac{2 \\pi}{3}$", "$r = 4$, $\\theta = \\frac{\\pi}{3}$", "$r = 4$, $\\theta = \\frac{4 \\pi}{3}$"]'::jsonb, 0, '$r = |z| = 4$ and $\theta = \arg z = \frac{2 \pi}{3}$, since $z = 4(\cos(\frac{2 \pi}{3}) + i\sin(\frac{2 \pi}{3}))$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Express $z = - \sqrt{2} + (\sqrt{2})i$ in polar form $z = r(\cos\theta + i\sin\theta)$, giving $r$ and $\theta$ (with $0 \leq \theta \leq \pi$).', '["$r = 2$, $\\theta = \\frac{3 \\pi}{4}$", "$r = 3$, $\\theta = \\frac{3 \\pi}{4}$", "$r = 2$, $\\theta = \\frac{3 \\pi}{8}$", "$r = 2$, $\\theta = \\frac{3 \\pi}{2}$"]'::jsonb, 0, '$r = |z| = 2$ and $\theta = \arg z = \frac{3 \pi}{4}$, since $z = 2(\cos(\frac{3 \pi}{4}) + i\sin(\frac{3 \pi}{4}))$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Express $z = - 2 \sqrt{3} + (2)i$ in polar form $z = r(\cos\theta + i\sin\theta)$, giving $r$ and $\theta$ (with $0 \leq \theta \leq \pi$).', '["$r = 4$, $\\theta = \\frac{5 \\pi}{6}$", "$r = 5$, $\\theta = \\frac{5 \\pi}{6}$", "$r = 4$, $\\theta = \\frac{5 \\pi}{12}$", "$r = 4$, $\\theta = \\frac{5 \\pi}{3}$"]'::jsonb, 0, '$r = |z| = 4$ and $\theta = \arg z = \frac{5 \pi}{6}$, since $z = 4(\cos(\frac{5 \pi}{6}) + i\sin(\frac{5 \pi}{6}))$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Express $z = -5 + (0)i$ in polar form $z = r(\cos\theta + i\sin\theta)$, giving $r$ and $\theta$ (with $0 \leq \theta \leq \pi$).', '["$r = 5$, $\\theta = \\pi$", "$r = 6$, $\\theta = \\pi$", "$r = 5$, $\\theta = \\frac{\\pi}{2}$", "$r = 5$, $\\theta = 2 \\pi$"]'::jsonb, 0, '$r = |z| = 5$ and $\theta = \arg z = \pi$, since $z = 5(\cos(\pi) + i\sin(\pi))$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos30^\circ + i\sin30^\circ)^3$.', '["$\\cos(3\\times30^\\circ) + i\\sin(3\\times30^\\circ) = 0 + (1)i$", "$\\cos(30^\\circ) + i\\sin(30^\\circ) = \\frac{\\sqrt{3}}{2} + (\\frac{1}{2})i$", "$3(\\cos30^\\circ + i\\sin30^\\circ)$, i.e. simply multiplied by 3, not raised to the power 3", "$\\cos(3\\times30^\\circ) - i\\sin(3\\times30^\\circ) = 0 - (1)i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=30^\circ$ and $n=3$, this is $\cos(90^\circ)+i\sin(90^\circ) = 0 + (1)i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos45^\circ + i\sin45^\circ)^4$.', '["$\\cos(4\\times45^\\circ) + i\\sin(4\\times45^\\circ) = -1 + (0)i$", "$\\cos(45^\\circ) + i\\sin(45^\\circ) = \\frac{\\sqrt{2}}{2} + (\\frac{\\sqrt{2}}{2})i$", "$4(\\cos45^\\circ + i\\sin45^\\circ)$, i.e. simply multiplied by 4, not raised to the power 4", "$\\cos(4\\times45^\\circ) - i\\sin(4\\times45^\\circ) = -1 - (0)i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=45^\circ$ and $n=4$, this is $\cos(180^\circ)+i\sin(180^\circ) = -1 + (0)i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos60^\circ + i\sin60^\circ)^3$.', '["$\\cos(3\\times60^\\circ) + i\\sin(3\\times60^\\circ) = -1 + (0)i$", "$\\cos(60^\\circ) + i\\sin(60^\\circ) = \\frac{1}{2} + (\\frac{\\sqrt{3}}{2})i$", "$3(\\cos60^\\circ + i\\sin60^\\circ)$, i.e. simply multiplied by 3, not raised to the power 3", "$\\cos(3\\times60^\\circ) - i\\sin(3\\times60^\\circ) = -1 - (0)i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=60^\circ$ and $n=3$, this is $\cos(180^\circ)+i\sin(180^\circ) = -1 + (0)i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos90^\circ + i\sin90^\circ)^2$.', '["$\\cos(2\\times90^\\circ) + i\\sin(2\\times90^\\circ) = -1 + (0)i$", "$\\cos(90^\\circ) + i\\sin(90^\\circ) = 0 + (1)i$", "$2(\\cos90^\\circ + i\\sin90^\\circ)$, i.e. simply multiplied by 2, not raised to the power 2", "$\\cos(2\\times90^\\circ) - i\\sin(2\\times90^\\circ) = -1 - (0)i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=90^\circ$ and $n=2$, this is $\cos(180^\circ)+i\sin(180^\circ) = -1 + (0)i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos90^\circ + i\sin90^\circ)^4$.', '["$\\cos(4\\times90^\\circ) + i\\sin(4\\times90^\\circ) = 1 + (0)i$", "$\\cos(90^\\circ) + i\\sin(90^\\circ) = 0 + (1)i$", "$4(\\cos90^\\circ + i\\sin90^\\circ)$, i.e. simply multiplied by 4, not raised to the power 4", "$\\cos(4\\times90^\\circ) - i\\sin(4\\times90^\\circ) = 1 - (0)i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=90^\circ$ and $n=4$, this is $\cos(360^\circ)+i\sin(360^\circ) = 1 + (0)i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos30^\circ + i\sin30^\circ)^6$.', '["$\\cos(6\\times30^\\circ) + i\\sin(6\\times30^\\circ) = -1 + (0)i$", "$\\cos(30^\\circ) + i\\sin(30^\\circ) = \\frac{\\sqrt{3}}{2} + (\\frac{1}{2})i$", "$6(\\cos30^\\circ + i\\sin30^\\circ)$, i.e. simply multiplied by 6, not raised to the power 6", "$\\cos(6\\times30^\\circ) - i\\sin(6\\times30^\\circ) = -1 - (0)i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=30^\circ$ and $n=6$, this is $\cos(180^\circ)+i\sin(180^\circ) = -1 + (0)i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos45^\circ + i\sin45^\circ)^2$.', '["$\\cos(2\\times45^\\circ) + i\\sin(2\\times45^\\circ) = 0 + (1)i$", "$\\cos(45^\\circ) + i\\sin(45^\\circ) = \\frac{\\sqrt{2}}{2} + (\\frac{\\sqrt{2}}{2})i$", "$2(\\cos45^\\circ + i\\sin45^\\circ)$, i.e. simply multiplied by 2, not raised to the power 2", "$\\cos(2\\times45^\\circ) - i\\sin(2\\times45^\\circ) = 0 - (1)i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=45^\circ$ and $n=2$, this is $\cos(90^\circ)+i\sin(90^\circ) = 0 + (1)i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos60^\circ + i\sin60^\circ)^6$.', '["$\\cos(6\\times60^\\circ) + i\\sin(6\\times60^\\circ) = 1 + (0)i$", "$\\cos(60^\\circ) + i\\sin(60^\\circ) = \\frac{1}{2} + (\\frac{\\sqrt{3}}{2})i$", "$6(\\cos60^\\circ + i\\sin60^\\circ)$, i.e. simply multiplied by 6, not raised to the power 6", "$\\cos(6\\times60^\\circ) - i\\sin(6\\times60^\\circ) = 1 - (0)i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=60^\circ$ and $n=6$, this is $\cos(360^\circ)+i\sin(360^\circ) = 1 + (0)i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos120^\circ + i\sin120^\circ)^3$.', '["$\\cos(3\\times120^\\circ) + i\\sin(3\\times120^\\circ) = 1 + (0)i$", "$\\cos(120^\\circ) + i\\sin(120^\\circ) = - \\frac{1}{2} + (\\frac{\\sqrt{3}}{2})i$", "$3(\\cos120^\\circ + i\\sin120^\\circ)$, i.e. simply multiplied by 3, not raised to the power 3", "$\\cos(3\\times120^\\circ) - i\\sin(3\\times120^\\circ) = 1 - (0)i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=120^\circ$ and $n=3$, this is $\cos(360^\circ)+i\sin(360^\circ) = 1 + (0)i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem, simplify $(\cos150^\circ + i\sin150^\circ)^2$.', '["$\\cos(2\\times150^\\circ) + i\\sin(2\\times150^\\circ) = \\frac{1}{2} + (- \\frac{\\sqrt{3}}{2})i$", "$\\cos(150^\\circ) + i\\sin(150^\\circ) = - \\frac{\\sqrt{3}}{2} + (\\frac{1}{2})i$", "$2(\\cos150^\\circ + i\\sin150^\\circ)$, i.e. simply multiplied by 2, not raised to the power 2", "$\\cos(2\\times150^\\circ) - i\\sin(2\\times150^\\circ) = \\frac{1}{2} - (- \\frac{\\sqrt{3}}{2})i$"]'::jsonb, 0, 'De Moivre''s theorem gives $(\cos\theta+i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$, so with $\theta=150^\circ$ and $n=2$, this is $\cos(300^\circ)+i\sin(300^\circ) = \frac{1}{2} + (- \frac{\sqrt{3}}{2})i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'De Moivre''s theorem states that for any integer $n$, $(\cos\theta + i\sin\theta)^n$ equals:', '["$\\cos(n\\theta) + i\\sin(n\\theta)$", "$n\\cos\\theta + in\\sin\\theta$", "$\\cos\\theta^n + i\\sin\\theta^n$", "$n(\\cos\\theta + i\\sin\\theta)$"]'::jsonb, 0, 'De Moivre''s theorem: $(\cos\theta + i\sin\theta)^n = \cos(n\theta) + i\sin(n\theta)$ for every integer $n$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using De Moivre''s theorem with $n=2$, which trigonometric identity is obtained by expanding $(\cos\theta+i\sin\theta)^2$ and comparing real parts?', '["$\\cos 2\\theta = \\cos^2\\theta - \\sin^2\\theta$", "$\\cos 2\\theta = 2\\sin\\theta\\cos\\theta$", "$\\cos 2\\theta = \\sin^2\\theta - \\cos^2\\theta$", "$\\cos 2\\theta = \\cos^2\\theta + \\sin^2\\theta$"]'::jsonb, 0, 'Expanding $(\cos\theta+i\sin\theta)^2 = \cos^2\theta - \sin^2\theta + i(2\sin\theta\cos\theta)$ and comparing with $\cos2\theta+i\sin2\theta$ gives $\cos2\theta = \cos^2\theta-\sin^2\theta$ (and $\sin2\theta = 2\sin\theta\cos\theta$).', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Expanding $(\cos\theta + i\sin\theta)^3$ by the binomial theorem and comparing imaginary parts with $\sin3\theta$ gives which identity?', '["$\\sin 3\\theta = 3\\cos^2\\theta\\sin\\theta - \\sin^3\\theta$", "$\\sin 3\\theta = \\cos^3\\theta - 3\\sin^2\\theta\\cos\\theta$", "$\\sin 3\\theta = 3\\sin\\theta - 4\\sin^3\\theta$ only, with no cosine terms", "$\\sin 3\\theta = \\sin^3\\theta$"]'::jsonb, 0, 'Expanding $(\cos\theta+i\sin\theta)^3$ and collecting the imaginary terms gives $\sin3\theta = 3\cos^2\theta\sin\theta - \sin^3\theta$ (equivalent, after using $\cos^2\theta=1-\sin^2\theta$, to $3\sin\theta-4\sin^3\theta$).', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all square roots of 1 (i.e. solve $z^2 = 1$), expressing each root in the form $x+iy$.', '["$1$, $-1$", "Only the real root(s) exist; the equation $z^2=1$ has no complex solutions", "There are $2n = 4$ distinct roots, not $n$", "$1$ (a single repeated root of multiplicity 2)"]'::jsonb, 0, 'By the $n$th-roots theorem, $z^2=\beta$ has exactly $n$ distinct solutions $z_k = r^{1/2}(\cos\frac{\theta+2k\pi}{2} + i\sin\frac{\theta+2k\pi}{2})$ for $k=0,\ldots,1$, giving $1$, $-1$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all square roots of -1 (i.e. solve $z^2 = -1$), expressing each root in the form $x+iy$.', '["$i$, $-i$", "Only the real root(s) exist; the equation $z^2=-1$ has no complex solutions", "There are $2n = 4$ distinct roots, not $n$", "$1$ (a single repeated root of multiplicity 2)"]'::jsonb, 0, 'By the $n$th-roots theorem, $z^2=\beta$ has exactly $n$ distinct solutions $z_k = r^{1/2}(\cos\frac{\theta+2k\pi}{2} + i\sin\frac{\theta+2k\pi}{2})$ for $k=0,\ldots,1$, giving $i$, $-i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all cube roots of 1 (i.e. solve $z^3 = 1$), expressing each root in the form $x+iy$.', '["$1$, $- \\frac{1}{2} + \\frac{\\sqrt{3}}{2}i$, $- \\frac{1}{2} - \\frac{\\sqrt{3}}{2}i$", "Only the real root(s) exist; the equation $z^3=1$ has no complex solutions", "There are $2n = 6$ distinct roots, not $n$", "$1$ (a single repeated root of multiplicity 3)"]'::jsonb, 0, 'By the $n$th-roots theorem, $z^3=\beta$ has exactly $n$ distinct solutions $z_k = r^{1/3}(\cos\frac{\theta+2k\pi}{3} + i\sin\frac{\theta+2k\pi}{3})$ for $k=0,\ldots,2$, giving $1$, $- \frac{1}{2} + \frac{\sqrt{3}}{2}i$, $- \frac{1}{2} - \frac{\sqrt{3}}{2}i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all cube roots of 8 (i.e. solve $z^3 = 8$), expressing each root in the form $x+iy$.', '["$2$, $-1 + \\sqrt{3}i$, $-1 - \\sqrt{3}i$", "Only the real root(s) exist; the equation $z^3=8$ has no complex solutions", "There are $2n = 6$ distinct roots, not $n$", "$2$ (a single repeated root of multiplicity 3)"]'::jsonb, 0, 'By the $n$th-roots theorem, $z^3=\beta$ has exactly $n$ distinct solutions $z_k = r^{1/3}(\cos\frac{\theta+2k\pi}{3} + i\sin\frac{\theta+2k\pi}{3})$ for $k=0,\ldots,2$, giving $2$, $-1 + \sqrt{3}i$, $-1 - \sqrt{3}i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all cube roots of -8 (i.e. solve $z^3 = -8$), expressing each root in the form $x+iy$.', '["$1 + \\sqrt{3}i$, $-2$, $1 - \\sqrt{3}i$", "Only the real root(s) exist; the equation $z^3=-8$ has no complex solutions", "There are $2n = 6$ distinct roots, not $n$", "$2$ (a single repeated root of multiplicity 3)"]'::jsonb, 0, 'By the $n$th-roots theorem, $z^3=\beta$ has exactly $n$ distinct solutions $z_k = r^{1/3}(\cos\frac{\theta+2k\pi}{3} + i\sin\frac{\theta+2k\pi}{3})$ for $k=0,\ldots,2$, giving $1 + \sqrt{3}i$, $-2$, $1 - \sqrt{3}i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all fourth roots of 16 (i.e. solve $z^4 = 16$), expressing each root in the form $x+iy$.', '["$2$, $2i$, $-2$, $-2i$", "Only the real root(s) exist; the equation $z^4=16$ has no complex solutions", "There are $2n = 8$ distinct roots, not $n$", "$2$ (a single repeated root of multiplicity 4)"]'::jsonb, 0, 'By the $n$th-roots theorem, $z^4=\beta$ has exactly $n$ distinct solutions $z_k = r^{1/4}(\cos\frac{\theta+2k\pi}{4} + i\sin\frac{\theta+2k\pi}{4})$ for $k=0,\ldots,3$, giving $2$, $2i$, $-2$, $-2i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all fourth roots of 1 (i.e. solve $z^4 = 1$), expressing each root in the form $x+iy$.', '["$1$, $i$, $-1$, $-i$", "Only the real root(s) exist; the equation $z^4=1$ has no complex solutions", "There are $2n = 8$ distinct roots, not $n$", "$1$ (a single repeated root of multiplicity 4)"]'::jsonb, 0, 'By the $n$th-roots theorem, $z^4=\beta$ has exactly $n$ distinct solutions $z_k = r^{1/4}(\cos\frac{\theta+2k\pi}{4} + i\sin\frac{\theta+2k\pi}{4})$ for $k=0,\ldots,3$, giving $1$, $i$, $-1$, $-i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all sixth roots of -1 (i.e. solve $z^6 = -1$), expressing each root in the form $x+iy$.', '["$\\frac{\\sqrt{3}}{2} + \\frac{1}{2}i$, $i$, $- \\frac{\\sqrt{3}}{2} + \\frac{1}{2}i$, $- \\frac{\\sqrt{3}}{2} - \\frac{1}{2}i$, $-i$, $\\frac{\\sqrt{3}}{2} - \\frac{1}{2}i$", "Only the real root(s) exist; the equation $z^6=-1$ has no complex solutions", "There are $2n = 12$ distinct roots, not $n$", "$1$ (a single repeated root of multiplicity 6)"]'::jsonb, 0, 'By the $n$th-roots theorem, $z^6=\beta$ has exactly $n$ distinct solutions $z_k = r^{1/6}(\cos\frac{\theta+2k\pi}{6} + i\sin\frac{\theta+2k\pi}{6})$ for $k=0,\ldots,5$, giving $\frac{\sqrt{3}}{2} + \frac{1}{2}i$, $i$, $- \frac{\sqrt{3}}{2} + \frac{1}{2}i$, $- \frac{\sqrt{3}}{2} - \frac{1}{2}i$, $-i$, $\frac{\sqrt{3}}{2} - \frac{1}{2}i$.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'According to the fundamental theorem on roots of complex numbers, how many distinct $n$th roots does a nonzero complex number $\beta$ have?', '["Exactly $n$ distinct roots", "Exactly 1 root", "Exactly 2 roots, regardless of $n$", "Infinitely many roots"]'::jsonb, 0, 'For $\beta \neq 0$ and integer $n \geq 1$, the equation $z^n = \beta$ has exactly $n$ distinct solutions, evenly spaced around a circle of radius $|\beta|^{1/n}$ in the complex plane.', 'Polar Form and De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Euler''s formula states that for real $\theta$, $e^{i\theta}$ equals:', '["$\\cos\\theta + i\\sin\\theta$", "$\\cos\\theta - i\\sin\\theta$", "$\\cosh\\theta + i\\sinh\\theta$", "$1 + i\\theta$"]'::jsonb, 0, 'Euler''s formula: $e^{i\theta} = \cos\theta + i\sin\theta$.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For a complex number $z = x+iy$, the complex exponential $e^z$ is defined as:', '["$e^x(\\cos y + i\\sin y)$", "$e^x + e^{iy}$", "$e^x \\cdot e^y$", "$e^{x} \\cos y - i e^x \\sin y$"]'::jsonb, 0, 'Writing $e^z = e^{x+iy} = e^x e^{iy}$ and applying Euler''s formula to $e^{iy}$ gives $e^z = e^x(\cos y + i\sin y)$.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $e^{0+i(\frac{\pi}{3})}$ in the form $a+bi$.', '["$\\frac{1}{2} + \\frac{\\sqrt{3}}{2}i$", "$- \\frac{1}{2} + \\frac{\\sqrt{3}}{2}i$", "$\\frac{1}{2} - \\frac{\\sqrt{3}}{2}i$", "$1$"]'::jsonb, 0, '$e^{0+i(\frac{\pi}{3})} = e^{0}(\cos(\frac{\pi}{3}) + i\sin(\frac{\pi}{3})) = \frac{1}{2} + \frac{\sqrt{3}}{2}i$.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which identity correctly defines the hyperbolic cosine of a complex (or real) variable $z$ in terms of the exponential function?', '["$\\cosh z = \\dfrac{e^z + e^{-z}}{2}$", "$\\cosh z = \\dfrac{e^z - e^{-z}}{2}$", "$\\cosh z = e^z + e^{-z}$", "$\\cosh z = \\dfrac{e^z - e^{-z}}{2i}$"]'::jsonb, 0, 'By definition, $\cosh z = \dfrac{e^z+e^{-z}}{2}$.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which identity correctly defines the hyperbolic sine of a complex (or real) variable $z$?', '["$\\sinh z = \\dfrac{e^z - e^{-z}}{2}$", "$\\sinh z = \\dfrac{e^z + e^{-z}}{2}$", "$\\sinh z = e^z - e^{-z}$", "$\\sinh z = \\dfrac{e^z + e^{-z}}{2i}$"]'::jsonb, 0, 'By definition, $\sinh z = \dfrac{e^z-e^{-z}}{2}$.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'What is the fundamental identity relating $\cosh^2 z$ and $\sinh^2 z$, analogous to $\cos^2\theta+\sin^2\theta=1$ for circular functions?', '["$\\cosh^2 z - \\sinh^2 z = 1$", "$\\cosh^2 z + \\sinh^2 z = 1$", "$\\cosh^2 z - \\sinh^2 z = 0$", "$\\cosh^2 z + \\sinh^2 z = 0$"]'::jsonb, 0, 'Substituting the exponential definitions of $\cosh z$ and $\sinh z$ and expanding gives $\cosh^2 z - \sinh^2 z = 1$, the hyperbolic analogue of the Pythagorean identity.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'How is $\cosh(ix)$, for real $x$, related to the ordinary (circular) cosine function?', '["$\\cosh(ix) = \\cos x$", "$\\cosh(ix) = -\\cos x$", "$\\cosh(ix) = i\\cos x$", "$\\cosh(ix) = \\sin x$"]'::jsonb, 0, '$\cosh(ix) = \dfrac{e^{ix}+e^{-ix}}{2} = \cos x$, using Euler''s formula on both exponentials.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'How is $\sinh(ix)$, for real $x$, related to the ordinary (circular) sine function?', '["$\\sinh(ix) = i\\sin x$", "$\\sinh(ix) = \\sin x$", "$\\sinh(ix) = -i\\sin x$", "$\\sinh(ix) = \\cos x$"]'::jsonb, 0, '$\sinh(ix) = \dfrac{e^{ix}-e^{-ix}}{2} = i\sin x$, using Euler''s formula on both exponentials.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'How is $\cos(iy)$, for real $y$, related to the hyperbolic cosine function?', '["$\\cos(iy) = \\cosh y$", "$\\cos(iy) = \\sinh y$", "$\\cos(iy) = -\\cosh y$", "$\\cos(iy) = i\\sinh y$"]'::jsonb, 0, 'Substituting $\theta = iy$ into $\cos\theta = \dfrac{e^{i\theta}+e^{-i\theta}}{2}$ gives $\cos(iy) = \dfrac{e^{-y}+e^{y}}{2} = \cosh y$.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'How is $\sin(iy)$, for real $y$, related to the hyperbolic sine function?', '["$\\sin(iy) = i\\sinh y$", "$\\sin(iy) = \\sinh y$", "$\\sin(iy) = -i\\sinh y$", "$\\sin(iy) = \\cosh y$"]'::jsonb, 0, 'Substituting $\theta=iy$ into $\sin\theta = \dfrac{e^{i\theta}-e^{-i\theta}}{2i}$ gives $\sin(iy) = i\sinh y$.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'What is $|e^{i\theta}|$ for real $\theta$?', '["$1$, for every real $\\theta$", "$\\theta$", "$e^\\theta$", "$0$"]'::jsonb, 0, '$|e^{i\theta}| = |\cos\theta + i\sin\theta| = \sqrt{\cos^2\theta+\sin^2\theta} = 1$, so $e^{i\theta}$ always lies on the unit circle.', 'Exponential and Hyperbolic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A complex-valued function $w = f(z)$ of a complex variable $z = x+iy$ can always be written in which standard form?', '["$f(z) = u(x,y) + iv(x,y)$, where $u$ and $v$ are real-valued functions of $x$ and $y$", "$f(z) = u(x) + iv(y)$ only, with $u$ depending solely on $x$", "$f(z) = u(x,y)$ alone, since complex functions have no imaginary part", "$f(z) = u(z) \\cdot iv(z)$"]'::jsonb, 0, 'Writing $z=x+iy$ and separating the real and imaginary parts of $f(z)$ gives $f(z) = u(x,y) + iv(x,y)$, the standard decomposition used throughout complex analysis.', 'Functions of a Complex Variable', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A function $f$ that assigns exactly one value $w$ to each $z$ in its domain is called:', '["A single-valued function", "A multi-valued function", "An analytic function, regardless of how many outputs it has", "A harmonic function"]'::jsonb, 0, 'By definition, a single-valued function assigns exactly one $w=f(z)$ to each $z$; if more than one value can be assigned (as with $z^{1/2}$ unless a branch is fixed), the function is multi-valued.', 'Functions of a Complex Variable', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following complex functions is naturally multi-valued (without further restriction)?', '["$f(z) = z^{1/2}$", "$f(z) = z^2$", "$f(z) = 3z + 1$", "$f(z) = e^z$"]'::jsonb, 0, 'Every nonzero $z$ has two distinct square roots, so $z^{1/2}$ assigns two values to each $z$ unless a specific branch is chosen -- it is multi-valued, unlike $z^2$, $3z+1$, or $e^z$.', 'Functions of a Complex Variable', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Writing $z = x+iy$, expand $f(z) = z^2$ and identify $u(x,y)$ and $v(x,y)$ where $f(z) = u+iv$.', '["$u = x^{2} - y^{2}$, $v = 2 x y$", "$u = 2 x y$, $v = x^{2} - y^{2}$", "$u = x^{2} - y^{2}$, $v = -2 x y$", "$u = x$, $v = y$"]'::jsonb, 0, 'Expanding $(x+iy)^2$ and using $i^2=-1$ (and $i^3=-i$ where needed) and collecting real and imaginary terms gives $u = x^{2} - y^{2}$ and $v = 2 x y$.', 'Functions of a Complex Variable', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Writing $z = x+iy$, expand $f(z) = z^3$ and identify $u(x,y)$ and $v(x,y)$ where $f(z) = u+iv$.', '["$u = x^{3} - 3 x y^{2}$, $v = 3 x^{2} y - y^{3}$", "$u = 3 x^{2} y - y^{3}$, $v = x^{3} - 3 x y^{2}$", "$u = x^{3} - 3 x y^{2}$, $v = -3 x^{2} y - y^{3}$", "$u = x$, $v = y$"]'::jsonb, 0, 'Expanding $(x+iy)^3$ and using $i^2=-1$ (and $i^3=-i$ where needed) and collecting real and imaginary terms gives $u = x^{3} - 3 x y^{2}$ and $v = 3 x^{2} y - y^{3}$.', 'Functions of a Complex Variable', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(z) = \bar z$ (the complex conjugate map), what are $u(x,y)$ and $v(x,y)$?', '["$u = x$, $v = -y$", "$u = x$, $v = y$", "$u = -x$, $v = y$", "$u = y$, $v = x$"]'::jsonb, 0, 'Since $\bar z = x - iy$, comparing with $u+iv$ gives $u=x$ and $v=-y$.', 'Functions of a Complex Variable', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(z) = |z|^2$, what are $u(x,y)$ and $v(x,y)$?', '["$u = x^2+y^2$, $v = 0$", "$u = x^2-y^2$, $v = 2xy$", "$u = 0$, $v = x^2+y^2$", "$u = x+y$, $v=0$"]'::jsonb, 0, '$|z|^2 = z\bar z = x^2+y^2$ is purely real, so $u = x^2+y^2$ and $v=0$.', 'Functions of a Complex Variable', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $u(x,y) = x^{2} - y^{2}$ and $v(x,y) = 2 x y$, do the Cauchy-Riemann equations $u_x = v_y$ and $u_y = -v_x$ hold?', '["They satisfies the Cauchy-Riemann equations", "They do NOT satisfy the Cauchy-Riemann equations", "The Cauchy-Riemann equations do not apply to real-valued functions of two variables", "Only $u_x=v_y$ needs to be checked; $u_y=-v_x$ is automatic"]'::jsonb, 0, '$u_x = 2 x$, $u_y = - 2 y$, $v_x = 2 y$, $v_y = 2 x$. Since $u_x=v_y$ and $u_y=-v_x$ both hold, the equations are satisfied.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $u(x,y) = x^{3} - 3 x y^{2}$ and $v(x,y) = 3 x^{2} y - y^{3}$, do the Cauchy-Riemann equations $u_x = v_y$ and $u_y = -v_x$ hold?', '["They satisfies the Cauchy-Riemann equations", "They do NOT satisfy the Cauchy-Riemann equations", "The Cauchy-Riemann equations do not apply to real-valued functions of two variables", "Only $u_x=v_y$ needs to be checked; $u_y=-v_x$ is automatic"]'::jsonb, 0, '$u_x = 3 x^{2} - 3 y^{2}$, $u_y = - 6 x y$, $v_x = 6 x y$, $v_y = 3 x^{2} - 3 y^{2}$. Since $u_x=v_y$ and $u_y=-v_x$ both hold, the equations are satisfied.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $u(x,y) = e^{x} \cos{\left(y \right)}$ and $v(x,y) = e^{x} \sin{\left(y \right)}$, do the Cauchy-Riemann equations $u_x = v_y$ and $u_y = -v_x$ hold?', '["They satisfies the Cauchy-Riemann equations", "They do NOT satisfy the Cauchy-Riemann equations", "The Cauchy-Riemann equations do not apply to real-valued functions of two variables", "Only $u_x=v_y$ needs to be checked; $u_y=-v_x$ is automatic"]'::jsonb, 0, '$u_x = e^{x} \cos{\left(y \right)}$, $u_y = - e^{x} \sin{\left(y \right)}$, $v_x = e^{x} \sin{\left(y \right)}$, $v_y = e^{x} \cos{\left(y \right)}$. Since $u_x=v_y$ and $u_y=-v_x$ both hold, the equations are satisfied.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $u(x,y) = x$ and $v(x,y) = - y$, do the Cauchy-Riemann equations $u_x = v_y$ and $u_y = -v_x$ hold?', '["They does NOT satisfy the Cauchy-Riemann equations", "They satisfy the Cauchy-Riemann equations", "The Cauchy-Riemann equations do not apply to real-valued functions of two variables", "Only $u_x=v_y$ needs to be checked; $u_y=-v_x$ is automatic"]'::jsonb, 0, '$u_x = 1$, $u_y = 0$, $v_x = 0$, $v_y = -1$. Since $u_x \neq v_y$ or $u_y \neq -v_x$, the equations fail.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $u(x,y) = x^{2} + y^{2}$ and $v(x,y) = 0$, do the Cauchy-Riemann equations $u_x = v_y$ and $u_y = -v_x$ hold?', '["They does NOT satisfy the Cauchy-Riemann equations", "They satisfy the Cauchy-Riemann equations", "The Cauchy-Riemann equations do not apply to real-valued functions of two variables", "Only $u_x=v_y$ needs to be checked; $u_y=-v_x$ is automatic"]'::jsonb, 0, '$u_x = 2 x$, $u_y = 2 y$, $v_x = 0$, $v_y = 0$. Since $u_x \neq v_y$ or $u_y \neq -v_x$, the equations fail.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $u(x,y) = x$ and $v(x,y) = y$, do the Cauchy-Riemann equations $u_x = v_y$ and $u_y = -v_x$ hold?', '["They satisfies the Cauchy-Riemann equations", "They do NOT satisfy the Cauchy-Riemann equations", "The Cauchy-Riemann equations do not apply to real-valued functions of two variables", "Only $u_x=v_y$ needs to be checked; $u_y=-v_x$ is automatic"]'::jsonb, 0, '$u_x = 1$, $u_y = 0$, $v_x = 0$, $v_y = 1$. Since $u_x=v_y$ and $u_y=-v_x$ both hold, the equations are satisfied.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $u(x,y) = 2 x y$ and $v(x,y) = - x^{2} + y^{2}$, do the Cauchy-Riemann equations $u_x = v_y$ and $u_y = -v_x$ hold?', '["They satisfies the Cauchy-Riemann equations", "They do NOT satisfy the Cauchy-Riemann equations", "The Cauchy-Riemann equations do not apply to real-valued functions of two variables", "Only $u_x=v_y$ needs to be checked; $u_y=-v_x$ is automatic"]'::jsonb, 0, '$u_x = 2 y$, $u_y = 2 x$, $v_x = - 2 x$, $v_y = 2 y$. Since $u_x=v_y$ and $u_y=-v_x$ both hold, the equations are satisfied.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The Cauchy-Riemann equations for $f(z) = u(x,y) + iv(x,y)$ to be differentiable at a point are:', '["$u_x = v_y$ and $u_y = -v_x$", "$u_x = v_x$ and $u_y = v_y$", "$u_x = -v_y$ and $u_y = v_x$", "$u_x = v_y$ and $u_y = v_x$"]'::jsonb, 0, 'The Cauchy-Riemann equations are $\dfrac{\partial u}{\partial x} = \dfrac{\partial v}{\partial y}$ and $\dfrac{\partial u}{\partial y} = -\dfrac{\partial v}{\partial x}$.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A function $f(z) = u+iv$ that is single-valued and differentiable throughout a domain $D$ is called:', '["Analytic (or holomorphic) in $D$", "Harmonic in $D$", "Conjugate in $D$", "Bounded in $D$"]'::jsonb, 0, 'A single-valued function that is differentiable at every point of a domain $D$ is called analytic (equivalently, holomorphic) in $D$.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A function $f(z)$ is analytic in a domain $D$ if and only if:', '["$u_x, u_y, v_x, v_y$ all exist, are continuous, and satisfy the Cauchy-Riemann equations throughout $D$", "$f(z)$ is bounded throughout $D$", "$u$ and $v$ are both polynomials", "$f(z)$ has a single value at just one point of $D$"]'::jsonb, 0, 'A function is analytic in $D$ iff the four first partial derivatives $u_x,u_y,v_x,v_y$ exist, are continuous, and satisfy the Cauchy-Riemann equations at every point of $D$.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The Cauchy-Riemann equations satisfied at a single isolated point, with no neighbourhood around it also satisfying them, are:', '["Not sufficient to guarantee analyticity at that point", "Always sufficient to guarantee analyticity at that point", "Irrelevant to the question of analyticity entirely", "Sufficient only when $u=v$"]'::jsonb, 0, 'Analyticity at a point requires differentiability throughout a neighbourhood of that point, not merely at the point itself; satisfying the Cauchy-Riemann equations only at an isolated point is not enough.', 'Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A real-valued function $u(x,y)$ is called harmonic in a domain $D$ if it satisfies:', '["Laplace''s equation $u_{xx} + u_{yy} = 0$ throughout $D$", "$u_{xx} - u_{yy} = 0$ throughout $D$", "$u_x = u_y$ throughout $D$", "$u_{xx} + u_{yy} = 1$ throughout $D$"]'::jsonb, 0, 'By definition, $u(x,y)$ is harmonic in $D$ if it satisfies Laplace''s equation $u_{xx}+u_{yy}=0$ throughout $D$.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(z) = u+iv$ is analytic in a domain $D$, what can be said about $u$ and $v$?', '["Both $u$ and $v$ are harmonic in $D$", "Only $u$ is harmonic; $v$ need not be", "Neither $u$ nor $v$ need be harmonic", "$u$ is harmonic only if $v=0$"]'::jsonb, 0, 'If $f=u+iv$ is analytic, the Cauchy-Riemann equations combined with the equality of mixed partials force both $u_{xx}+u_{yy}=0$ and $v_{xx}+v_{yy}=0$, so both $u$ and $v$ are harmonic.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'When $u$ and $v$ are both harmonic in a domain $D$ and together satisfy the Cauchy-Riemann equations (so that $f=u+iv$ is analytic), $v$ is called:', '["The harmonic conjugate of $u$", "The harmonic inverse of $u$", "The analytic root of $u$", "The Laplace transform of $u$"]'::jsonb, 0, 'When $v$ is harmonic and paired with $u$ via the Cauchy-Riemann equations, $v$ is called the harmonic conjugate of $u$.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is $u(x,y) = x^{2} - y^{2}$ harmonic (i.e. does it satisfy Laplace''s equation $u_{xx}+u_{yy}=0$)?', '["It IS harmonic ($u_{xx}+u_{yy} = 0$)", "It is NOT harmonic", "Harmonicity cannot be determined without also knowing $v$", "Every polynomial in $x$ and $y$ is automatically harmonic"]'::jsonb, 0, '$u_{xx} = 2$ and $u_{yy} = -2$, so $u_{xx}+u_{yy} = 0$, which is identically zero, so $u$ is harmonic.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is $u(x,y) = x^{3} - 3 x y^{2}$ harmonic (i.e. does it satisfy Laplace''s equation $u_{xx}+u_{yy}=0$)?', '["It IS harmonic ($u_{xx}+u_{yy} = 0$)", "It is NOT harmonic", "Harmonicity cannot be determined without also knowing $v$", "Every polynomial in $x$ and $y$ is automatically harmonic"]'::jsonb, 0, '$u_{xx} = 6 x$ and $u_{yy} = - 6 x$, so $u_{xx}+u_{yy} = 0$, which is identically zero, so $u$ is harmonic.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is $u(x,y) = e^{x} \cos{\left(y \right)}$ harmonic (i.e. does it satisfy Laplace''s equation $u_{xx}+u_{yy}=0$)?', '["It IS harmonic ($u_{xx}+u_{yy} = 0$)", "It is NOT harmonic", "Harmonicity cannot be determined without also knowing $v$", "Every polynomial in $x$ and $y$ is automatically harmonic"]'::jsonb, 0, '$u_{xx} = e^{x} \cos{\left(y \right)}$ and $u_{yy} = - e^{x} \cos{\left(y \right)}$, so $u_{xx}+u_{yy} = 0$, which is identically zero, so $u$ is harmonic.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is $u(x,y) = x^{2} + y^{2}$ harmonic (i.e. does it satisfy Laplace''s equation $u_{xx}+u_{yy}=0$)?', '["It is NOT harmonic ($u_{xx}+u_{yy} = 4$)", "It IS harmonic", "Harmonicity cannot be determined without also knowing $v$", "Every polynomial in $x$ and $y$ is automatically harmonic"]'::jsonb, 0, '$u_{xx} = 2$ and $u_{yy} = 2$, so $u_{xx}+u_{yy} = 4$, which is not identically zero, so $u$ is not harmonic.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is $u(x,y) = x^{4} - y^{4}$ harmonic (i.e. does it satisfy Laplace''s equation $u_{xx}+u_{yy}=0$)?', '["It is NOT harmonic ($u_{xx}+u_{yy} = 12 x^{2} - 12 y^{2}$)", "It IS harmonic", "Harmonicity cannot be determined without also knowing $v$", "Every polynomial in $x$ and $y$ is automatically harmonic"]'::jsonb, 0, '$u_{xx} = 12 x^{2}$ and $u_{yy} = - 12 y^{2}$, so $u_{xx}+u_{yy} = 12 x^{2} - 12 y^{2}$, which is not identically zero, so $u$ is not harmonic.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is $u(x,y) = 2 x y$ harmonic (i.e. does it satisfy Laplace''s equation $u_{xx}+u_{yy}=0$)?', '["It IS harmonic ($u_{xx}+u_{yy} = 0$)", "It is NOT harmonic", "Harmonicity cannot be determined without also knowing $v$", "Every polynomial in $x$ and $y$ is automatically harmonic"]'::jsonb, 0, '$u_{xx} = 0$ and $u_{yy} = 0$, so $u_{xx}+u_{yy} = 0$, which is identically zero, so $u$ is harmonic.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $u$ and $v$ are harmonic conjugates (so $f=u+iv$ is analytic), what is the geometric relationship between the level curves $u=\text{const}$ and $v=\text{const}$?', '["They form two orthogonal (perpendicular) families of curves", "They are always parallel to each other", "They coincide exactly", "They have no fixed relationship"]'::jsonb, 0, 'The gradients $\nabla u$ and $\nabla v$ are perpendicular wherever $f''(z)\neq0$ (a direct consequence of the Cauchy-Riemann equations), so the level curves of $u$ and $v$ intersect at right angles.', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which function is the harmonic conjugate of $u(x,y) = 2xy$ (up to an additive constant), so that $f(z) = u+iv$ is analytic?', '["$v = y^2 - x^2$", "$v = x^2 - y^2$", "$v = 2xy$", "$v = x^2+y^2$"]'::jsonb, 0, 'With $u=2xy$: $u_x=2y$, $u_y=2x$. Requiring $v_y=u_x=2y$ gives $v=y^2+g(x)$; requiring $v_x=-u_y=-2x$ gives $g''(x)=-2x$, so $g(x)=-x^2$, giving $v=y^2-x^2$ (up to a constant).', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which function is the harmonic conjugate of $u(x,y) = x^2-y^2$ (up to an additive constant)?', '["$v = 2xy$", "$v = x^2+y^2$", "$v = xy$", "$v = y^2-x^2$"]'::jsonb, 0, 'With $u=x^2-y^2$: $u_x=2x$, $u_y=-2y$. Requiring $v_y=u_x=2x$ gives $v=2xy+g(x)$; requiring $v_x=-u_y=2y$ gives $2y+g''(x)=2y$, so $g''(x)=0$, giving $v=2xy$ (up to a constant).', 'Harmonic Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which chain of inclusions correctly orders the standard number systems from smallest to largest?', '["$\\mathbb{N} \\subset \\mathbb{Z} \\subset \\mathbb{Q} \\subset \\mathbb{R} \\subset \\mathbb{C}$", "$\\mathbb{Z} \\subset \\mathbb{N} \\subset \\mathbb{Q} \\subset \\mathbb{R} \\subset \\mathbb{C}$", "$\\mathbb{N} \\subset \\mathbb{Q} \\subset \\mathbb{Z} \\subset \\mathbb{R} \\subset \\mathbb{C}$", "$\\mathbb{N} \\subset \\mathbb{Z} \\subset \\mathbb{R} \\subset \\mathbb{Q} \\subset \\mathbb{C}$"]'::jsonb, 0, 'The natural numbers sit inside the integers, which sit inside the rationals, which sit inside the reals, which sit inside the complex numbers: $\mathbb{N} \subset \mathbb{Z} \subset \mathbb{Q} \subset \mathbb{R} \subset \mathbb{C}$.', 'Number Systems', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following numbers is rational but NOT an integer?', '["$\\dfrac{3}{4}$", "$-7$", "$0$", "$\\sqrt{2}$"]'::jsonb, 0, '$3/4$ can be written as a ratio of integers but is not itself a whole number, so it is rational but not an integer. $\sqrt2$ is irrational, and $-7, 0$ are integers.', 'Number Systems', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following numbers is real but NOT rational (i.e. irrational)?', '["$\\sqrt{2}$", "$\\dfrac{1}{3}$", "$-5$", "$0.75$"]'::jsonb, 0, '$\sqrt2$ cannot be written as a ratio of integers, so it is irrational; the other three are all rational.', 'Number Systems', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following numbers is complex but NOT real?', '["$3 + 2i$", "$\\pi$", "$-4$", "$\\sqrt{5}$"]'::jsonb, 0, '$3+2i$ has a nonzero imaginary part, so it lies in $\mathbb{C}\setminus\mathbb{R}$; the others are all real numbers (and hence also complex, with zero imaginary part).', 'Number Systems', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The set of natural numbers $\mathbb{N}$ is typically taken to be:', '["$\\{1, 2, 3, 4, \\ldots\\}$ (or, in some conventions, including $0$)", "$\\{\\ldots, -2, -1, 0, 1, 2, \\ldots\\}$", "$\\{\\text{all fractions } p/q\\}$", "$\\{\\text{all real numbers}\\}$"]'::jsonb, 0, 'The natural numbers are the counting numbers $1,2,3,\ldots$ (some conventions include $0$); the set of all positive and negative whole numbers together is $\mathbb{Z}$, not $\mathbb{N}$.', 'Number Systems', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A field satisfies the trichotomy law for order if, for any two elements $a$ and $b$, exactly one of which of the following holds?', '["$a < b$, $a = b$, or $a > b$", "$a < b$ and $a > b$ simultaneously", "$a = b$ only", "$a \\leq b$ and $b \\leq a$ never both hold"]'::jsonb, 0, 'The trichotomy law states that for real numbers $a,b$, exactly one of $a<b$, $a=b$, $a>b$ holds.', 'The Real Number System', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The real number system $\mathbb{R}$ is described as a ''complete ordered field''. Which property does completeness refer to?', '["Every nonempty subset of $\\mathbb{R}$ that is bounded above has a least upper bound in $\\mathbb{R}$", "Every real number has a multiplicative inverse", "Every pair of real numbers can be compared", "Every real number is either positive or negative"]'::jsonb, 0, 'Completeness (the least upper bound property) states that every nonempty subset of $\mathbb{R}$ bounded above has a supremum in $\mathbb{R}$ -- this is what distinguishes $\mathbb{R}$ from $\mathbb{Q}$, which lacks this property (e.g. $\{x\in\mathbb{Q}: x^2<2\}$ has no rational supremum).', 'The Real Number System', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $A = \{2, 4, 6, 8, 10\}$. Find $\sup A$ (the supremum, or least upper bound, of $A$).', '["$10$", "$11$", "$2$", "$A$ has no supremum"]'::jsonb, 0, 'For a finite set, the supremum is simply its maximum element: $\sup A = \max A = 10$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $A = \{2, 4, 6, 8, 10\}$. Find $\inf A$ (the infimum, or greatest lower bound, of $A$).', '["$2$", "$1$", "$10$", "$A$ has no infimum"]'::jsonb, 0, 'For a finite set, the infimum is simply its minimum element: $\inf A = \min A = 2$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $A = \{1, 3, 5, 7\}$. Find $\sup A$ (the supremum, or least upper bound, of $A$).', '["$7$", "$8$", "$1$", "$A$ has no supremum"]'::jsonb, 0, 'For a finite set, the supremum is simply its maximum element: $\sup A = \max A = 7$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $A = \{1, 3, 5, 7\}$. Find $\inf A$ (the infimum, or greatest lower bound, of $A$).', '["$1$", "$0$", "$7$", "$A$ has no infimum"]'::jsonb, 0, 'For a finite set, the infimum is simply its minimum element: $\inf A = \min A = 1$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $A = \{-3, -1, 0, 5\}$. Find $\sup A$ (the supremum, or least upper bound, of $A$).', '["$5$", "$6$", "$-3$", "$A$ has no supremum"]'::jsonb, 0, 'For a finite set, the supremum is simply its maximum element: $\sup A = \max A = 5$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $A = \{-3, -1, 0, 5\}$. Find $\inf A$ (the infimum, or greatest lower bound, of $A$).', '["$-3$", "$-4$", "$5$", "$A$ has no infimum"]'::jsonb, 0, 'For a finite set, the infimum is simply its minimum element: $\inf A = \min A = -3$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The interval $A = (-1, 5)$ is bounded above by 5 and below by -1. Find $\sup A$.', '["$5$", "$6$", "$A$ has no supremum, since it is unbounded above", "$\\sup A = \\infty$ literally, as a real number"]'::jsonb, 0, 'Since $A$ is bounded above by $5$ and this bound is approached arbitrarily closely (or attained, if the interval is closed at that end), $\sup A = 5$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The interval $A = (-1, 5)$ is bounded above by 5 and below by -1. Find $\inf A$.', '["$-1$", "$-2$", "$A$ has no infimum, since it is unbounded below", "$\\inf A = -\\infty$ literally, as a real number"]'::jsonb, 0, 'Since $A$ is bounded below by $-1$ and this bound is approached arbitrarily closely (or attained, if the interval is closed at that end), $\inf A = -1$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The interval $A = [-3, 7]$ is bounded above by 7 and below by -3. Find $\sup A$.', '["$7$", "$8$", "$A$ has no supremum, since it is unbounded above", "$\\sup A = \\infty$ literally, as a real number"]'::jsonb, 0, 'Since $A$ is bounded above by $7$ and this bound is approached arbitrarily closely (or attained, if the interval is closed at that end), $\sup A = 7$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The interval $A = [-3, 7]$ is bounded above by 7 and below by -3. Find $\inf A$.', '["$-3$", "$-4$", "$A$ has no infimum, since it is unbounded below", "$\\inf A = -\\infty$ literally, as a real number"]'::jsonb, 0, 'Since $A$ is bounded below by $-3$ and this bound is approached arbitrarily closely (or attained, if the interval is closed at that end), $\inf A = -3$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The interval $A = (-\infty, 4]$ is bounded above by 4, but not bounded below. Find $\sup A$.', '["$4$", "$5$", "$A$ has no supremum, since it is unbounded above", "$\\sup A = \\infty$ literally, as a real number"]'::jsonb, 0, 'Since $A$ is bounded above by $4$ and this bound is approached arbitrarily closely (or attained, if the interval is closed at that end), $\sup A = 4$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The interval $A = [-2, \infty)$ is bounded below by -2, but not bounded above. Is $A$ bounded above?', '["No -- $A$ is not bounded above, so $\\sup A$ does not exist as a real number", "Yes -- $A$ is bounded above by 0", "Yes -- every subset of $\\mathbb{R}$ is bounded above", "$A$ has no infimum either"]'::jsonb, 0, 'Since $A$ extends to $+\infty$ with no upper bound, $A$ is not bounded above, so it has no (finite) supremum.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The interval $A = [-2, \infty)$ is bounded below by -2, but not bounded above. Find $\inf A$.', '["$-2$", "$-3$", "$A$ has no infimum, since it is unbounded below", "$\\inf A = -\\infty$ literally, as a real number"]'::jsonb, 0, 'Since $A$ is bounded below by $-2$ and this bound is approached arbitrarily closely (or attained, if the interval is closed at that end), $\inf A = -2$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A set $A \subseteq \mathbb{R}$ is said to be bounded if:', '["It is bounded both above and below (i.e. contained in some interval $[m, M]$)", "It is bounded above only", "It is bounded below only", "It contains only positive numbers"]'::jsonb, 0, 'A set is bounded when it is bounded both above and below, i.e. there exist real numbers $m \leq M$ such that $m \leq x \leq M$ for every $x \in A$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If a set $A$ has a maximum element (i.e. an element of $A$ that is also an upper bound for $A$), how does $\sup A$ relate to $\max A$?', '["$\\sup A = \\max A$", "$\\sup A > \\max A$ always", "$\\sup A$ does not exist when $\\max A$ exists", "$\\sup A = \\max A + 1$"]'::jsonb, 0, 'When a set has an actual maximum element, that maximum is automatically the least upper bound, so $\sup A = \max A$.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the open interval $A = (0, 1)$, which statement about $\max A$ and $\sup A$ is correct?', '["$\\sup A = 1$, but $A$ has no maximum element (since $1 \\notin A$)", "$\\max A = 1$ and $\\sup A = 1$", "Neither $\\sup A$ nor $\\max A$ exist", "$\\sup A = 0$"]'::jsonb, 0, 'Every element of $(0,1)$ is less than 1, and 1 is the least such upper bound, so $\sup A = 1$; but since $1 \notin A$, no element of $A$ actually attains this bound, so $A$ has no maximum.', 'Bounded Sets and Sup/Inf', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\displaystyle\lim_{n\to\infty} \dfrac{4n^2-1n-3}{2n^2+3}$.', '["$2$", "$0$", "$3$", "$5$"]'::jsonb, 0, 'Dividing numerator and denominator by the highest power $n^2$, the lower-order terms vanish as $n\to\infty$, leaving the ratio of leading coefficients: $\dfrac{4}{2} = 2$.', 'Sequences of Real Numbers', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\displaystyle\lim_{n\to\infty} \dfrac{3n^2+2n-2}{4n^2+5n+6}$.', '["$\\frac{3}{4}$", "$0$", "$\\frac{7}{4}$", "$\\frac{2}{5}$"]'::jsonb, 0, 'Dividing numerator and denominator by the highest power $n^2$, the lower-order terms vanish as $n\to\infty$, leaving the ratio of leading coefficients: $\dfrac{3}{4} = \frac{3}{4}$.', 'Sequences of Real Numbers', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\displaystyle\lim_{n\to\infty} \dfrac{5n^2-6n+6}{2n^2+4n-6}$.', '["$\\frac{5}{2}$", "$\\frac{7}{2}$", "$- \\frac{3}{2}$", "$0$"]'::jsonb, 0, 'Dividing numerator and denominator by the highest power $n^2$, the lower-order terms vanish as $n\to\infty$, leaving the ratio of leading coefficients: $\dfrac{5}{2} = \frac{5}{2}$.', 'Sequences of Real Numbers', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\displaystyle\lim_{n\to\infty} \dfrac{4n^2-4n-4}{3n^2-4n-2}$.', '["$\\frac{4}{3}$", "$\\frac{7}{3}$", "$1$", "$0$"]'::jsonb, 0, 'Dividing numerator and denominator by the highest power $n^2$, the lower-order terms vanish as $n\to\infty$, leaving the ratio of leading coefficients: $\dfrac{4}{3} = \frac{4}{3}$.', 'Sequences of Real Numbers', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\displaystyle\lim_{n\to\infty} \dfrac{5n^2+3n-6}{1n^2+6n+3}$.', '["$5$", "$0$", "$6$", "$\\frac{1}{2}$"]'::jsonb, 0, 'Dividing numerator and denominator by the highest power $n^2$, the lower-order terms vanish as $n\to\infty$, leaving the ratio of leading coefficients: $\dfrac{5}{1} = 5$.', 'Sequences of Real Numbers', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\displaystyle\lim_{n\to\infty} \dfrac{1n^2-2}{2n^2-5n+5}$.', '["$\\frac{1}{2}$", "$0$", "$\\frac{3}{2}$", "$\\frac{7}{2}$"]'::jsonb, 0, 'Dividing numerator and denominator by the highest power $n^2$, the lower-order terms vanish as $n\to\infty$, leaving the ratio of leading coefficients: $\dfrac{1}{2} = \frac{1}{2}$.', 'Sequences of Real Numbers', false, 'second', 2),
