  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (t^{2} - 3, 3 t^{2} + 4 t - 4, - t^{2} + 2 t - 2)$, find $\vec r''(t)$.', '["$(2 t, 6 t + 4, 2 - 2 t)$", "$(2 t + 1, 6 t + 4, 2 - 2 t)$", "$(2 t, 6 t + 3, 2 - 2 t)$", "$(t^{2} - 3, 3 t^{2} + 4 t - 4, - t^{2} + 2 t - 2)$"]'::jsonb, 0, 'Differentiating each component: $\vec r''(t) = (2 t, 6 t + 4, 2 - 2 t)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (- 3 t^{2} - 4 t + 4, - 2 t^{2} + 3 t - 2, - 2 t^{2} + 4 t + 4)$, find $\vec r''(t)$.', '["$(- 6 t - 4, 3 - 4 t, 4 - 4 t)$", "$(- 6 t - 3, 3 - 4 t, 4 - 4 t)$", "$(- 6 t - 4, 2 - 4 t, 4 - 4 t)$", "$(- 3 t^{2} - 4 t + 4, - 2 t^{2} + 3 t - 2, - 2 t^{2} + 4 t + 4)$"]'::jsonb, 0, 'Differentiating each component: $\vec r''(t) = (- 6 t - 4, 3 - 4 t, 4 - 4 t)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (2 t^{2} + 2 t - 1, 3 t^{2} - 4 t + 3, 3 t^{2} + 2 t - 3)$, find $\vec r''(t)$.', '["$(4 t + 2, 6 t - 4, 6 t + 2)$", "$(4 t + 3, 6 t - 4, 6 t + 2)$", "$(4 t + 2, 6 t - 5, 6 t + 2)$", "$(2 t^{2} + 2 t - 1, 3 t^{2} - 4 t + 3, 3 t^{2} + 2 t - 3)$"]'::jsonb, 0, 'Differentiating each component: $\vec r''(t) = (4 t + 2, 6 t - 4, 6 t + 2)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (- t^{2} - 3 t + 2, t^{3})$, find $\vec r''(0)$.', '["$(-3, 0)$", "$(-2, 0)$", "$(-3, -1)$", "$(2, 0)$"]'::jsonb, 0, '$\vec r''(t) = (- 2 t - 3, 3 t^{2})$, so $\vec r''(0) = (-3, 0)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (- 3 t - 2, - 2 t^{3} + 3 t)$, find $\vec r''(-1)$.', '["$(-3, -3)$", "$(-2, -3)$", "$(-3, -4)$", "$(1, -1)$"]'::jsonb, 0, '$\vec r''(t) = (-3, 3 - 6 t^{2})$, so $\vec r''(-1) = (-3, -3)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (2 - t^{2}, - 3 t^{3} - 3 t)$, find $\vec r''(1)$.', '["$(-2, -12)$", "$(-1, -12)$", "$(-2, -13)$", "$(1, -6)$"]'::jsonb, 0, '$\vec r''(t) = (- 2 t, - 9 t^{2} - 3)$, so $\vec r''(1) = (-2, -12)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (- 3 t - 2, - 3 t^{3} - 2 t)$, find $\vec r''(1)$.', '["$(-3, -11)$", "$(-2, -11)$", "$(-3, -12)$", "$(-5, -5)$"]'::jsonb, 0, '$\vec r''(t) = (-3, - 9 t^{2} - 2)$, so $\vec r''(1) = (-3, -11)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (- 3 t^{2} + 3 t - 3, t^{3})$, find $\vec r''(2)$.', '["$(-9, 12)$", "$(-8, 12)$", "$(-9, 11)$", "$(-9, 8)$"]'::jsonb, 0, '$\vec r''(t) = (3 - 6 t, 3 t^{2})$, so $\vec r''(2) = (-9, 12)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (2 t - 1, t^{3} - 2 t)$, find $\vec r''(1)$.', '["$(2, 1)$", "$(3, 1)$", "$(2, 0)$", "$(1, -1)$"]'::jsonb, 0, '$\vec r''(t) = (2, 3 t^{2} - 2)$, so $\vec r''(1) = (2, 1)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (t^{2} + 2 t + 1, 2 t^{3} - 2 t)$, find $\vec r''(-2)$.', '["$(-2, 22)$", "$(-1, 22)$", "$(-2, 21)$", "$(1, -12)$"]'::jsonb, 0, '$\vec r''(t) = (2 t + 2, 6 t^{2} - 2)$, so $\vec r''(-2) = (-2, 22)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (- t^{2} - 2 t + 3, 2 t^{3})$, find $\vec r''(2)$.', '["$(-6, 24)$", "$(-5, 24)$", "$(-6, 23)$", "$(-5, 16)$"]'::jsonb, 0, '$\vec r''(t) = (- 2 t - 2, 6 t^{2})$, so $\vec r''(2) = (-6, 24)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (2 t^{2} + 2 t, t^{3} - 3 t)$, find $\vec r''(-2)$.', '["$(-6, 9)$", "$(-5, 9)$", "$(-6, 8)$", "$(4, -2)$"]'::jsonb, 0, '$\vec r''(t) = (4 t + 2, 3 t^{2} - 3)$, so $\vec r''(-2) = (-6, 9)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (- 2 t^{2} + 2 t + 2, t^{3})$, find $\vec r''(-1)$.', '["$(6, 3)$", "$(7, 3)$", "$(6, 2)$", "$(-2, -1)$"]'::jsonb, 0, '$\vec r''(t) = (2 - 4 t, 3 t^{2})$, so $\vec r''(-1) = (6, 3)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (- 2 t^{2} + 2 t - 3, 3 t^{3} - 2 t)$, find $\vec r''(-1)$.', '["$(6, 7)$", "$(7, 7)$", "$(6, 6)$", "$(-7, -1)$"]'::jsonb, 0, '$\vec r''(t) = (2 - 4 t, 9 t^{2} - 2)$, so $\vec r''(-1) = (6, 7)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (2 t^{2} + t - 2, - t^{3} - 2 t)$, find $\vec r''(2)$.', '["$(9, -14)$", "$(10, -14)$", "$(9, -15)$", "$(8, -12)$"]'::jsonb, 0, '$\vec r''(t) = (4 t + 1, - 3 t^{2} - 2)$, so $\vec r''(2) = (9, -14)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (1 - 3 t, - 2 t^{3} + 2 t)$, find $\vec r''(-1)$.', '["$(-3, -4)$", "$(-2, -4)$", "$(-3, -5)$", "$(4, 0)$"]'::jsonb, 0, '$\vec r''(t) = (-3, 2 - 6 t^{2})$, so $\vec r''(-1) = (-3, -4)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (- 2 t^{2} + t + 3, 3 t^{3} - 2 t)$, find $\vec r''(2)$.', '["$(-7, 34)$", "$(-6, 34)$", "$(-7, 33)$", "$(-3, 20)$"]'::jsonb, 0, '$\vec r''(t) = (1 - 4 t, 9 t^{2} - 2)$, so $\vec r''(2) = (-7, 34)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t) = (t - 2, 3 t^{3} - 2 t)$, find $\vec r''(3)$.', '["$(1, 79)$", "$(2, 79)$", "$(1, 78)$", "$(1, 75)$"]'::jsonb, 0, '$\vec r''(t) = (1, 9 t^{2} - 2)$, so $\vec r''(3) = (1, 79)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For differentiable vector functions $\vec u(t)$ and $\vec v(t)$, the derivative of their dot product satisfies:', '["$\\dfrac{d}{dt}(\\vec u \\cdot \\vec v) = \\vec u'' \\cdot \\vec v + \\vec u \\cdot \\vec v''$", "$\\dfrac{d}{dt}(\\vec u \\cdot \\vec v) = \\vec u'' \\cdot \\vec v''$", "$\\dfrac{d}{dt}(\\vec u \\cdot \\vec v) = |\\vec u''||\\vec v''|$", "$\\dfrac{d}{dt}(\\vec u \\cdot \\vec v) = \\vec u \\cdot \\vec v$ (a constant)"]'::jsonb, 0, 'The dot product obeys a Leibniz-style product rule: $\frac{d}{dt}(\vec u\cdot\vec v) = \vec u''\cdot\vec v + \vec u\cdot\vec v''$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For differentiable vector functions $\vec u(t)$ and $\vec v(t)$, the derivative of their cross product satisfies:', '["$\\dfrac{d}{dt}(\\vec u \\times \\vec v) = \\vec u'' \\times \\vec v + \\vec u \\times \\vec v''$ (order matters, since cross product is not commutative)", "$\\dfrac{d}{dt}(\\vec u \\times \\vec v) = \\vec u'' \\times \\vec v''$", "$\\dfrac{d}{dt}(\\vec u \\times \\vec v) = \\vec v \\times \\vec u$", "$\\dfrac{d}{dt}(\\vec u \\times \\vec v) = 0$ always"]'::jsonb, 0, 'The cross product also obeys a product rule, but the ORDER of each term must be preserved since $\vec a \times \vec b \neq \vec b\times\vec a$: $\frac{d}{dt}(\vec u\times\vec v) = \vec u''\times\vec v + \vec u\times\vec v''$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec r(t)$ has constant magnitude (i.e. $|\vec r(t)|$ is the same for every $t$), what can be concluded about $\vec r(t) \cdot \vec r''(t)$?', '["$\\vec r(t) \\cdot \\vec r''(t) = 0$ for every $t$ -- the vector and its derivative are always perpendicular", "$\\vec r(t) \\cdot \\vec r''(t)$ is a nonzero constant", "$\\vec r''(t) = 0$ for every $t$", "Nothing can be concluded"]'::jsonb, 0, 'Differentiating $\vec r \cdot \vec r = |\vec r|^2 = \text{const}$ with respect to $t$ using the product rule gives $2\vec r\cdot\vec r'' = 0$, so $\vec r\cdot\vec r''=0$ -- a vector of constant length is always perpendicular to its own derivative (this is why, for example, position and velocity are perpendicular on a circular path of constant radius).', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For a scalar function $\phi(t)$ and vector function $\vec u(t)$, the derivative of the product $\phi(t)\vec u(t)$ is given by:', '["$\\phi''(t)\\vec u(t) + \\phi(t)\\vec u''(t)$", "$\\phi''(t)\\vec u''(t)$", "$\\phi(t)\\vec u(t)$ (unchanged)", "$\\phi''(t) + \\vec u''(t)$"]'::jsonb, 0, 'The scalar-times-vector product also follows the ordinary product rule: $\dfrac{d}{dt}[\phi(t)\vec u(t)] = \phi''(t)\vec u(t) + \phi(t)\vec u''(t)$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (2 t, 4 t^{2}, t)$, find the tangent vector $\vec r''(2)$ and its magnitude (the speed) at $t=2$.', '["$\\vec r''(2) = (2, 16, 1)$, with speed $|\\vec r''(2)| = 3 \\sqrt{29}$", "$\\vec r''(2) = (2, 16, 1)$, with speed $|\\vec r''(2)| = 1 + 3 \\sqrt{29}$", "$\\vec r''(2) = (3, 17, 2)$, with speed $|\\vec r''(2)| = 3 \\sqrt{29}$", "$\\vec r''(2) = (2 t, 4 t^{2}, t)$, with speed $|\\vec r''(2)| = 3 \\sqrt{29}$"]'::jsonb, 0, '$\vec r''(t) = (2, 8 t, 1)$, so $\vec r''(2) = (2, 16, 1)$, and the speed is $|\vec r''(2)| = \sqrt{(2)^2+(16)^2+(1)^2} = 3 \sqrt{29}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (3 t, 4 t^{2}, 2 t)$, find the tangent vector $\vec r''(1)$ and its magnitude (the speed) at $t=1$.', '["$\\vec r''(1) = (3, 8, 2)$, with speed $|\\vec r''(1)| = \\sqrt{77}$", "$\\vec r''(1) = (3, 8, 2)$, with speed $|\\vec r''(1)| = 1 + \\sqrt{77}$", "$\\vec r''(1) = (4, 9, 3)$, with speed $|\\vec r''(1)| = \\sqrt{77}$", "$\\vec r''(1) = (3 t, 4 t^{2}, 2 t)$, with speed $|\\vec r''(1)| = \\sqrt{77}$"]'::jsonb, 0, '$\vec r''(t) = (3, 8 t, 2)$, so $\vec r''(1) = (3, 8, 2)$, and the speed is $|\vec r''(1)| = \sqrt{(3)^2+(8)^2+(2)^2} = \sqrt{77}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (t, 2 t^{2}, - t)$, find the tangent vector $\vec r''(1)$ and its magnitude (the speed) at $t=1$.', '["$\\vec r''(1) = (1, 4, -1)$, with speed $|\\vec r''(1)| = 3 \\sqrt{2}$", "$\\vec r''(1) = (1, 4, -1)$, with speed $|\\vec r''(1)| = 1 + 3 \\sqrt{2}$", "$\\vec r''(1) = (2, 5, 0)$, with speed $|\\vec r''(1)| = 3 \\sqrt{2}$", "$\\vec r''(1) = (t, 2 t^{2}, - t)$, with speed $|\\vec r''(1)| = 3 \\sqrt{2}$"]'::jsonb, 0, '$\vec r''(t) = (1, 4 t, -1)$, so $\vec r''(1) = (1, 4, -1)$, and the speed is $|\vec r''(1)| = \sqrt{(1)^2+(4)^2+(-1)^2} = 3 \sqrt{2}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (3 t, t^{2}, - 2 t)$, find the tangent vector $\vec r''(1)$ and its magnitude (the speed) at $t=1$.', '["$\\vec r''(1) = (3, 2, -2)$, with speed $|\\vec r''(1)| = \\sqrt{17}$", "$\\vec r''(1) = (3, 2, -2)$, with speed $|\\vec r''(1)| = 1 + \\sqrt{17}$", "$\\vec r''(1) = (4, 3, -1)$, with speed $|\\vec r''(1)| = \\sqrt{17}$", "$\\vec r''(1) = (3 t, t^{2}, - 2 t)$, with speed $|\\vec r''(1)| = \\sqrt{17}$"]'::jsonb, 0, '$\vec r''(t) = (3, 2 t, -2)$, so $\vec r''(1) = (3, 2, -2)$, and the speed is $|\vec r''(1)| = \sqrt{(3)^2+(2)^2+(-2)^2} = \sqrt{17}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (3 t, 2 t^{2}, 0)$, find the tangent vector $\vec r''(1)$ and its magnitude (the speed) at $t=1$.', '["$\\vec r''(1) = (3, 4, 0)$, with speed $|\\vec r''(1)| = 5$", "$\\vec r''(1) = (3, 4, 0)$, with speed $|\\vec r''(1)| = 6$", "$\\vec r''(1) = (4, 5, 1)$, with speed $|\\vec r''(1)| = 5$", "$\\vec r''(1) = (3 t, 2 t^{2}, 0)$, with speed $|\\vec r''(1)| = 5$"]'::jsonb, 0, '$\vec r''(t) = (3, 4 t, 0)$, so $\vec r''(1) = (3, 4, 0)$, and the speed is $|\vec r''(1)| = \sqrt{(3)^2+(4)^2+(0)^2} = 5$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (2 t, 2 t^{2}, - 2 t)$, find the tangent vector $\vec r''(2)$ and its magnitude (the speed) at $t=2$.', '["$\\vec r''(2) = (2, 8, -2)$, with speed $|\\vec r''(2)| = 6 \\sqrt{2}$", "$\\vec r''(2) = (2, 8, -2)$, with speed $|\\vec r''(2)| = 1 + 6 \\sqrt{2}$", "$\\vec r''(2) = (3, 9, -1)$, with speed $|\\vec r''(2)| = 6 \\sqrt{2}$", "$\\vec r''(2) = (2 t, 2 t^{2}, - 2 t)$, with speed $|\\vec r''(2)| = 6 \\sqrt{2}$"]'::jsonb, 0, '$\vec r''(t) = (2, 4 t, -2)$, so $\vec r''(2) = (2, 8, -2)$, and the speed is $|\vec r''(2)| = \sqrt{(2)^2+(8)^2+(-2)^2} = 6 \sqrt{2}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (3 t, 4 t^{2}, - 3 t)$, find the tangent vector $\vec r''(2)$ and its magnitude (the speed) at $t=2$.', '["$\\vec r''(2) = (3, 16, -3)$, with speed $|\\vec r''(2)| = \\sqrt{274}$", "$\\vec r''(2) = (3, 16, -3)$, with speed $|\\vec r''(2)| = 1 + \\sqrt{274}$", "$\\vec r''(2) = (4, 17, -2)$, with speed $|\\vec r''(2)| = \\sqrt{274}$", "$\\vec r''(2) = (3 t, 4 t^{2}, - 3 t)$, with speed $|\\vec r''(2)| = \\sqrt{274}$"]'::jsonb, 0, '$\vec r''(t) = (3, 8 t, -3)$, so $\vec r''(2) = (3, 16, -3)$, and the speed is $|\vec r''(2)| = \sqrt{(3)^2+(16)^2+(-3)^2} = \sqrt{274}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (3 t, 2 t^{2}, - 3 t)$, find the tangent vector $\vec r''(2)$ and its magnitude (the speed) at $t=2$.', '["$\\vec r''(2) = (3, 8, -3)$, with speed $|\\vec r''(2)| = \\sqrt{82}$", "$\\vec r''(2) = (3, 8, -3)$, with speed $|\\vec r''(2)| = 1 + \\sqrt{82}$", "$\\vec r''(2) = (4, 9, -2)$, with speed $|\\vec r''(2)| = \\sqrt{82}$", "$\\vec r''(2) = (3 t, 2 t^{2}, - 3 t)$, with speed $|\\vec r''(2)| = \\sqrt{82}$"]'::jsonb, 0, '$\vec r''(t) = (3, 4 t, -3)$, so $\vec r''(2) = (3, 8, -3)$, and the speed is $|\vec r''(2)| = \sqrt{(3)^2+(8)^2+(-3)^2} = \sqrt{82}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (4 t, 4 t^{2}, - 2 t)$, find the tangent vector $\vec r''(1)$ and its magnitude (the speed) at $t=1$.', '["$\\vec r''(1) = (4, 8, -2)$, with speed $|\\vec r''(1)| = 2 \\sqrt{21}$", "$\\vec r''(1) = (4, 8, -2)$, with speed $|\\vec r''(1)| = 1 + 2 \\sqrt{21}$", "$\\vec r''(1) = (5, 9, -1)$, with speed $|\\vec r''(1)| = 2 \\sqrt{21}$", "$\\vec r''(1) = (4 t, 4 t^{2}, - 2 t)$, with speed $|\\vec r''(1)| = 2 \\sqrt{21}$"]'::jsonb, 0, '$\vec r''(t) = (4, 8 t, -2)$, so $\vec r''(1) = (4, 8, -2)$, and the speed is $|\vec r''(1)| = \sqrt{(4)^2+(8)^2+(-2)^2} = 2 \sqrt{21}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (t, 4 t^{2}, 2 t)$, find the tangent vector $\vec r''(2)$ and its magnitude (the speed) at $t=2$.', '["$\\vec r''(2) = (1, 16, 2)$, with speed $|\\vec r''(2)| = 3 \\sqrt{29}$", "$\\vec r''(2) = (1, 16, 2)$, with speed $|\\vec r''(2)| = 1 + 3 \\sqrt{29}$", "$\\vec r''(2) = (2, 17, 3)$, with speed $|\\vec r''(2)| = 3 \\sqrt{29}$", "$\\vec r''(2) = (t, 4 t^{2}, 2 t)$, with speed $|\\vec r''(2)| = 3 \\sqrt{29}$"]'::jsonb, 0, '$\vec r''(t) = (1, 8 t, 2)$, so $\vec r''(2) = (1, 16, 2)$, and the speed is $|\vec r''(2)| = \sqrt{(1)^2+(16)^2+(2)^2} = 3 \sqrt{29}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (2 t, 3 t^{2}, t)$, find the tangent vector $\vec r''(1)$ and its magnitude (the speed) at $t=1$.', '["$\\vec r''(1) = (2, 6, 1)$, with speed $|\\vec r''(1)| = \\sqrt{41}$", "$\\vec r''(1) = (2, 6, 1)$, with speed $|\\vec r''(1)| = 1 + \\sqrt{41}$", "$\\vec r''(1) = (3, 7, 2)$, with speed $|\\vec r''(1)| = \\sqrt{41}$", "$\\vec r''(1) = (2 t, 3 t^{2}, t)$, with speed $|\\vec r''(1)| = \\sqrt{41}$"]'::jsonb, 0, '$\vec r''(t) = (2, 6 t, 1)$, so $\vec r''(1) = (2, 6, 1)$, and the speed is $|\vec r''(1)| = \sqrt{(2)^2+(6)^2+(1)^2} = \sqrt{41}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (2 t, t^{2}, - 3 t)$, find the tangent vector $\vec r''(1)$ and its magnitude (the speed) at $t=1$.', '["$\\vec r''(1) = (2, 2, -3)$, with speed $|\\vec r''(1)| = \\sqrt{17}$", "$\\vec r''(1) = (2, 2, -3)$, with speed $|\\vec r''(1)| = 1 + \\sqrt{17}$", "$\\vec r''(1) = (3, 3, -2)$, with speed $|\\vec r''(1)| = \\sqrt{17}$", "$\\vec r''(1) = (2 t, t^{2}, - 3 t)$, with speed $|\\vec r''(1)| = \\sqrt{17}$"]'::jsonb, 0, '$\vec r''(t) = (2, 2 t, -3)$, so $\vec r''(1) = (2, 2, -3)$, and the speed is $|\vec r''(1)| = \sqrt{(2)^2+(2)^2+(-3)^2} = \sqrt{17}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the space curve $\vec r(t) = (t, 4 t^{2}, 0)$, find the tangent vector $\vec r''(2)$ and its magnitude (the speed) at $t=2$.', '["$\\vec r''(2) = (1, 16, 0)$, with speed $|\\vec r''(2)| = \\sqrt{257}$", "$\\vec r''(2) = (1, 16, 0)$, with speed $|\\vec r''(2)| = 1 + \\sqrt{257}$", "$\\vec r''(2) = (2, 17, 1)$, with speed $|\\vec r''(2)| = \\sqrt{257}$", "$\\vec r''(2) = (t, 4 t^{2}, 0)$, with speed $|\\vec r''(2)| = \\sqrt{257}$"]'::jsonb, 0, '$\vec r''(t) = (1, 8 t, 0)$, so $\vec r''(2) = (1, 16, 0)$, and the speed is $|\vec r''(2)| = \sqrt{(1)^2+(16)^2+(0)^2} = \sqrt{257}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For a space curve $\vec r(t)$, the unit tangent vector $\vec T(t)$ is defined as:', '["$\\vec T(t) = \\dfrac{\\vec r''(t)}{|\\vec r''(t)|}$, provided $\\vec r''(t) \\neq \\vec 0$", "$\\vec T(t) = \\vec r''(t)$ directly, with no normalization", "$\\vec T(t) = |\\vec r''(t)|$, a scalar", "$\\vec T(t) = \\vec r(t) \\times \\vec r''(t)$"]'::jsonb, 0, 'The unit tangent vector is the tangent (velocity) vector normalized to length 1: $\vec T(t) = \dfrac{\vec r''(t)}{|\vec r''(t)|}$.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The unit tangent vector $\vec T(t)$ to a curve, wherever it is defined, always has magnitude equal to:', '["$1$", "$|\\vec r''(t)|$", "$0$", "The arc length of the curve"]'::jsonb, 0, 'By construction $\vec T(t) = \vec r''(t)/|\vec r''(t)|$, dividing by its own magnitude, so $|\vec T(t)| = 1$ identically.', 'Differentiation of Vectors', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = 2 x^{2} y + 4 x y^{2} + x y$, find $\partial f/\partial y$.', '["$2 x^{2} + 8 x y + x$", "$4 x y + 4 y^{2} + y$", "$2 x^{2} + 8 x y + 2 x$", "$2 x^{2} + 8 x y + x - y$"]'::jsonb, 0, 'Differentiating with respect to $y$, treating $x$ as constant: $\partial f/\partial y = 2 x^{2} + 8 x y + x$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = 4 x^{2} y + 4 x y^{2}$, find $\partial f/\partial x$.', '["$8 x y + 4 y^{2}$", "$4 x^{2} + 8 x y$", "$8 x y + x + 4 y^{2}$", "$8 x y + 4 y^{2} - y$"]'::jsonb, 0, 'Differentiating with respect to $x$, treating $y$ as constant: $\partial f/\partial x = 8 x y + 4 y^{2}$.', 'Partial Differentiation', false, 'second', 2),
