  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = 3 x^{2} y + x y^{2} + 3 x y$, find $\partial f/\partial y$.', '["$3 x^{2} + 2 x y + 3 x$", "$6 x y + y^{2} + 3 y$", "$3 x^{2} + 2 x y + 4 x$", "$3 x^{2} + 2 x y + 3 x - y$"]'::jsonb, 0, 'Differentiating with respect to $y$, treating $x$ as constant: $\partial f/\partial y = 3 x^{2} + 2 x y + 3 x$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = 4 x^{2} y + 3 x y^{2} - 2 x y$, find $\partial f/\partial y$.', '["$4 x^{2} + 6 x y - 2 x$", "$8 x y + 3 y^{2} - 2 y$", "$4 x^{2} + 6 x y - x$", "$4 x^{2} + 6 x y - 2 x - y$"]'::jsonb, 0, 'Differentiating with respect to $y$, treating $x$ as constant: $\partial f/\partial y = 4 x^{2} + 6 x y - 2 x$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = 4 x^{2} y + 3 x y^{2} - 3 x y$, find $\partial f/\partial x$.', '["$8 x y + 3 y^{2} - 3 y$", "$4 x^{2} + 6 x y - 3 x$", "$8 x y + x + 3 y^{2} - 3 y$", "$8 x y + 3 y^{2} - 4 y$"]'::jsonb, 0, 'Differentiating with respect to $x$, treating $y$ as constant: $\partial f/\partial x = 8 x y + 3 y^{2} - 3 y$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = 4 x^{2} y + 2 x y^{2} + x y$, find $\partial f/\partial y$.', '["$4 x^{2} + 4 x y + x$", "$8 x y + 2 y^{2} + y$", "$4 x^{2} + 4 x y + 2 x$", "$4 x^{2} + 4 x y + x - y$"]'::jsonb, 0, 'Differentiating with respect to $y$, treating $x$ as constant: $\partial f/\partial y = 4 x^{2} + 4 x y + x$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = 3 x^{2} y + 3 x y^{2} - x y$, find $\partial f/\partial x$.', '["$6 x y + 3 y^{2} - y$", "$3 x^{2} + 6 x y - x$", "$6 x y + x + 3 y^{2} - y$", "$6 x y + 3 y^{2} - 2 y$"]'::jsonb, 0, 'Differentiating with respect to $x$, treating $y$ as constant: $\partial f/\partial x = 6 x y + 3 y^{2} - y$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{2} y + 3 x y^{2}$, find $\partial f/\partial y$.', '["$x^{2} + 6 x y$", "$2 x y + 3 y^{2}$", "$x^{2} + 6 x y + x$", "$x^{2} + 6 x y - y$"]'::jsonb, 0, 'Differentiating with respect to $y$, treating $x$ as constant: $\partial f/\partial y = x^{2} + 6 x y$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = 4 x^{2} y + 4 x y^{2} - 2 x y$, find $\partial f/\partial y$.', '["$4 x^{2} + 8 x y - 2 x$", "$8 x y + 4 y^{2} - 2 y$", "$4 x^{2} + 8 x y - x$", "$4 x^{2} + 8 x y - 2 x - y$"]'::jsonb, 0, 'Differentiating with respect to $y$, treating $x$ as constant: $\partial f/\partial y = 4 x^{2} + 8 x y - 2 x$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = 3 x^{2} y + 3 x y^{2}$, find $\partial f/\partial y$.', '["$3 x^{2} + 6 x y$", "$6 x y + 3 y^{2}$", "$3 x^{2} + 6 x y + x$", "$3 x^{2} + 6 x y - y$"]'::jsonb, 0, 'Differentiating with respect to $y$, treating $x$ as constant: $\partial f/\partial y = 3 x^{2} + 6 x y$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + x^{2} y + 2 x y^{2} + x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 6 x^{2} y + 2 x + 4 y + 1$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 6 x^{2} y + 2 x + 4 y + 1$ but $f_{yx} = 6 x^{2} y + 2 x + 4 y + 2$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 6 x^{2} y + 2 x + 4 y + 1$ and $f_{yx} = \partial_x(\partial_y f) = 6 x^{2} y + 2 x + 4 y + 1$ -- since both equal $6 x^{2} y + 2 x + 4 y + 1$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 3 x^{2} y + 4 x y^{2} + 3 x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 6 x^{2} y + 6 x + 8 y + 3$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 6 x^{2} y + 6 x + 8 y + 3$ but $f_{yx} = 6 x^{2} y + 6 x + 8 y + 4$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 6 x^{2} y + 6 x + 8 y + 3$ and $f_{yx} = \partial_x(\partial_y f) = 6 x^{2} y + 6 x + 8 y + 3$ -- since both equal $6 x^{2} y + 6 x + 8 y + 3$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 3 x^{2} y + 2 x y^{2}$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 2 \\left(3 x^{2} y + 3 x + 2 y\\right)$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 2 \\left(3 x^{2} y + 3 x + 2 y\\right)$ but $f_{yx} = 2 \\left(3 x^{2} y + 3 x + 2 y\\right) + 1$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 2 \left(3 x^{2} y + 3 x + 2 y\right)$ and $f_{yx} = \partial_x(\partial_y f) = 2 \left(3 x^{2} y + 3 x + 2 y\right)$ -- since both equal $2 \left(3 x^{2} y + 3 x + 2 y\right)$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 3 x^{2} y + 3 x y^{2} + 2 x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 2 \\left(3 x^{2} y + 3 x + 3 y + 1\\right)$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 2 \\left(3 x^{2} y + 3 x + 3 y + 1\\right)$ but $f_{yx} = 2 \\left(3 x^{2} y + 3 x + 3 y + 1\\right) + 1$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 2 \left(3 x^{2} y + 3 x + 3 y + 1\right)$ and $f_{yx} = \partial_x(\partial_y f) = 2 \left(3 x^{2} y + 3 x + 3 y + 1\right)$ -- since both equal $2 \left(3 x^{2} y + 3 x + 3 y + 1\right)$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 2 x^{2} y + 3 x y^{2} + 2 x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 2 \\left(3 x^{2} y + 2 x + 3 y + 1\\right)$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 2 \\left(3 x^{2} y + 2 x + 3 y + 1\\right)$ but $f_{yx} = 2 \\left(3 x^{2} y + 2 x + 3 y + 1\\right) + 1$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 2 \left(3 x^{2} y + 2 x + 3 y + 1\right)$ and $f_{yx} = \partial_x(\partial_y f) = 2 \left(3 x^{2} y + 2 x + 3 y + 1\right)$ -- since both equal $2 \left(3 x^{2} y + 2 x + 3 y + 1\right)$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 3 x^{2} y + x y^{2}$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 2 \\left(3 x^{2} y + 3 x + y\\right)$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 2 \\left(3 x^{2} y + 3 x + y\\right)$ but $f_{yx} = 2 \\left(3 x^{2} y + 3 x + y\\right) + 1$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 2 \left(3 x^{2} y + 3 x + y\right)$ and $f_{yx} = \partial_x(\partial_y f) = 2 \left(3 x^{2} y + 3 x + y\right)$ -- since both equal $2 \left(3 x^{2} y + 3 x + y\right)$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + x^{2} y + 2 x y^{2} - 2 x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 2 \\left(3 x^{2} y + x + 2 y - 1\\right)$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 2 \\left(3 x^{2} y + x + 2 y - 1\\right)$ but $f_{yx} = 2 \\left(3 x^{2} y + x + 2 y - 1\\right) + 1$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 2 \left(3 x^{2} y + x + 2 y - 1\right)$ and $f_{yx} = \partial_x(\partial_y f) = 2 \left(3 x^{2} y + x + 2 y - 1\right)$ -- since both equal $2 \left(3 x^{2} y + x + 2 y - 1\right)$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 2 x^{2} y + 3 x y^{2} - 2 x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 2 \\left(3 x^{2} y + 2 x + 3 y - 1\\right)$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 2 \\left(3 x^{2} y + 2 x + 3 y - 1\\right)$ but $f_{yx} = 2 \\left(3 x^{2} y + 2 x + 3 y - 1\\right) + 1$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 2 \left(3 x^{2} y + 2 x + 3 y - 1\right)$ and $f_{yx} = \partial_x(\partial_y f) = 2 \left(3 x^{2} y + 2 x + 3 y - 1\right)$ -- since both equal $2 \left(3 x^{2} y + 2 x + 3 y - 1\right)$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 2 x^{2} y + 2 x y^{2} + 2 x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 2 \\left(3 x^{2} y + 2 x + 2 y + 1\\right)$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 2 \\left(3 x^{2} y + 2 x + 2 y + 1\\right)$ but $f_{yx} = 2 \\left(3 x^{2} y + 2 x + 2 y + 1\\right) + 1$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 2 \left(3 x^{2} y + 2 x + 2 y + 1\right)$ and $f_{yx} = \partial_x(\partial_y f) = 2 \left(3 x^{2} y + 2 x + 2 y + 1\right)$ -- since both equal $2 \left(3 x^{2} y + 2 x + 2 y + 1\right)$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 3 x^{2} y + 3 x y^{2} - x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 6 x^{2} y + 6 x + 6 y - 1$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 6 x^{2} y + 6 x + 6 y - 1$ but $f_{yx} = 6 x^{2} y + 6 x + 6 y$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 6 x^{2} y + 6 x + 6 y - 1$ and $f_{yx} = \partial_x(\partial_y f) = 6 x^{2} y + 6 x + 6 y - 1$ -- since both equal $6 x^{2} y + 6 x + 6 y - 1$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 2 x^{2} y + 2 x y^{2} + 3 x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 6 x^{2} y + 4 x + 4 y + 3$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 6 x^{2} y + 4 x + 4 y + 3$ but $f_{yx} = 6 x^{2} y + 4 x + 4 y + 4$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 6 x^{2} y + 4 x + 4 y + 3$ and $f_{yx} = \partial_x(\partial_y f) = 6 x^{2} y + 4 x + 4 y + 3$ -- since both equal $6 x^{2} y + 4 x + 4 y + 3$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + 4 x^{2} y + 3 x y^{2} + x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 6 x^{2} y + 8 x + 6 y + 1$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 6 x^{2} y + 8 x + 6 y + 1$ but $f_{yx} = 6 x^{2} y + 8 x + 6 y + 2$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 6 x^{2} y + 8 x + 6 y + 1$ and $f_{yx} = \partial_x(\partial_y f) = 6 x^{2} y + 8 x + 6 y + 1$ -- since both equal $6 x^{2} y + 8 x + 6 y + 1$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(x,y) = x^{3} y^{2} + x^{2} y + x y^{2} - 3 x y$, compute the mixed partial derivatives $f_{xy}$ and $f_{yx}$. What do you find?', '["$f_{xy} = f_{yx} = 6 x^{2} y + 2 x + 2 y - 3$ -- the mixed partials are equal, as guaranteed when they are continuous", "$f_{xy} = 6 x^{2} y + 2 x + 2 y - 3$ but $f_{yx} = 6 x^{2} y + 2 x + 2 y - 2$ -- they differ", "Mixed partial derivatives can never be computed for polynomial functions", "$f_{xy} = 0$ regardless of $f$"]'::jsonb, 0, 'Computing directly, $f_{xy} = \partial_y(\partial_x f) = 6 x^{2} y + 2 x + 2 y - 3$ and $f_{yx} = \partial_x(\partial_y f) = 6 x^{2} y + 2 x + 2 y - 3$ -- since both equal $6 x^{2} y + 2 x + 2 y - 3$, this illustrates that for functions with continuous second partials, the order of differentiation does not matter.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For a function $f(x,y)$ with continuous second-order partial derivatives, how do the mixed partials $f_{xy}$ and $f_{yx}$ compare?', '["They are always equal: $f_{xy} = f_{yx}$", "They are always negatives of each other", "They are unrelated in general", "$f_{xy} = 2f_{yx}$ always"]'::jsonb, 0, 'By the equality of mixed partials (Clairaut''s/Schwarz''s theorem), if $f_{xy}$ and $f_{yx}$ are both continuous, then $f_{xy} = f_{yx}$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(x,y) = x^{2} y$, with $x = t$ and $y = t^{2}$, use the chain rule $\dfrac{df}{dt} = \dfrac{\partial f}{\partial x}\dfrac{dx}{dt} + \dfrac{\partial f}{\partial y}\dfrac{dy}{dt}$ to find $\dfrac{df}{dt}$.', '["$4 t^{3}$", "$4 t^{3} + t$", "$2 x y$", "$8 t^{3}$"]'::jsonb, 0, '$\dfrac{\partial f}{\partial x} = 2xy$, $\dfrac{\partial f}{\partial y} = x^2$, $\dfrac{dx}{dt}=1$, $\dfrac{dy}{dt}=2 t$. Substituting $x=t, y=t^{2}$ and simplifying gives $\dfrac{df}{dt} = 4 t^{3}$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(x,y) = x^{2} y$, with $x = t$ and $y = 3 t^{2}$, use the chain rule $\dfrac{df}{dt} = \dfrac{\partial f}{\partial x}\dfrac{dx}{dt} + \dfrac{\partial f}{\partial y}\dfrac{dy}{dt}$ to find $\dfrac{df}{dt}$.', '["$12 t^{3}$", "$12 t^{3} + t$", "$2 x y$", "$24 t^{3}$"]'::jsonb, 0, '$\dfrac{\partial f}{\partial x} = 2xy$, $\dfrac{\partial f}{\partial y} = x^2$, $\dfrac{dx}{dt}=1$, $\dfrac{dy}{dt}=6 t$. Substituting $x=t, y=3 t^{2}$ and simplifying gives $\dfrac{df}{dt} = 12 t^{3}$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(x,y) = x^{2} y$, with $x = 2 t$ and $y = t^{2}$, use the chain rule $\dfrac{df}{dt} = \dfrac{\partial f}{\partial x}\dfrac{dx}{dt} + \dfrac{\partial f}{\partial y}\dfrac{dy}{dt}$ to find $\dfrac{df}{dt}$.', '["$16 t^{3}$", "$16 t^{3} + t$", "$2 x y$", "$32 t^{3}$"]'::jsonb, 0, '$\dfrac{\partial f}{\partial x} = 2xy$, $\dfrac{\partial f}{\partial y} = x^2$, $\dfrac{dx}{dt}=2$, $\dfrac{dy}{dt}=2 t$. Substituting $x=2 t, y=t^{2}$ and simplifying gives $\dfrac{df}{dt} = 16 t^{3}$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(x,y) = x^{2} y$, with $x = 3 t$ and $y = t^{2}$, use the chain rule $\dfrac{df}{dt} = \dfrac{\partial f}{\partial x}\dfrac{dx}{dt} + \dfrac{\partial f}{\partial y}\dfrac{dy}{dt}$ to find $\dfrac{df}{dt}$.', '["$36 t^{3}$", "$36 t^{3} + t$", "$2 x y$", "$72 t^{3}$"]'::jsonb, 0, '$\dfrac{\partial f}{\partial x} = 2xy$, $\dfrac{\partial f}{\partial y} = x^2$, $\dfrac{dx}{dt}=3$, $\dfrac{dy}{dt}=2 t$. Substituting $x=3 t, y=t^{2}$ and simplifying gives $\dfrac{df}{dt} = 36 t^{3}$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(x,y) = x^{2} y$, with $x = 2 t$ and $y = 3 t^{2}$, use the chain rule $\dfrac{df}{dt} = \dfrac{\partial f}{\partial x}\dfrac{dx}{dt} + \dfrac{\partial f}{\partial y}\dfrac{dy}{dt}$ to find $\dfrac{df}{dt}$.', '["$48 t^{3}$", "$48 t^{3} + t$", "$2 x y$", "$96 t^{3}$"]'::jsonb, 0, '$\dfrac{\partial f}{\partial x} = 2xy$, $\dfrac{\partial f}{\partial y} = x^2$, $\dfrac{dx}{dt}=2$, $\dfrac{dy}{dt}=6 t$. Substituting $x=2 t, y=3 t^{2}$ and simplifying gives $\dfrac{df}{dt} = 48 t^{3}$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(x,y) = x^{2} y$, with $x = 3 t$ and $y = 2 t^{2}$, use the chain rule $\dfrac{df}{dt} = \dfrac{\partial f}{\partial x}\dfrac{dx}{dt} + \dfrac{\partial f}{\partial y}\dfrac{dy}{dt}$ to find $\dfrac{df}{dt}$.', '["$72 t^{3}$", "$72 t^{3} + t$", "$2 x y$", "$144 t^{3}$"]'::jsonb, 0, '$\dfrac{\partial f}{\partial x} = 2xy$, $\dfrac{\partial f}{\partial y} = x^2$, $\dfrac{dx}{dt}=3$, $\dfrac{dy}{dt}=4 t$. Substituting $x=3 t, y=2 t^{2}$ and simplifying gives $\dfrac{df}{dt} = 72 t^{3}$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(x,y) = x^{2} y$, with $x = 2 t$ and $y = 2 t^{2}$, use the chain rule $\dfrac{df}{dt} = \dfrac{\partial f}{\partial x}\dfrac{dx}{dt} + \dfrac{\partial f}{\partial y}\dfrac{dy}{dt}$ to find $\dfrac{df}{dt}$.', '["$32 t^{3}$", "$32 t^{3} + t$", "$2 x y$", "$64 t^{3}$"]'::jsonb, 0, '$\dfrac{\partial f}{\partial x} = 2xy$, $\dfrac{\partial f}{\partial y} = x^2$, $\dfrac{dx}{dt}=2$, $\dfrac{dy}{dt}=4 t$. Substituting $x=2 t, y=2 t^{2}$ and simplifying gives $\dfrac{df}{dt} = 32 t^{3}$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(x,y) = x^{2} y$, with $x = 3 t$ and $y = 3 t^{2}$, use the chain rule $\dfrac{df}{dt} = \dfrac{\partial f}{\partial x}\dfrac{dx}{dt} + \dfrac{\partial f}{\partial y}\dfrac{dy}{dt}$ to find $\dfrac{df}{dt}$.', '["$108 t^{3}$", "$108 t^{3} + t$", "$2 x y$", "$216 t^{3}$"]'::jsonb, 0, '$\dfrac{\partial f}{\partial x} = 2xy$, $\dfrac{\partial f}{\partial y} = x^2$, $\dfrac{dx}{dt}=3$, $\dfrac{dy}{dt}=6 t$. Substituting $x=3 t, y=3 t^{2}$ and simplifying gives $\dfrac{df}{dt} = 108 t^{3}$.', 'Partial Differentiation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A function $\phi(x,y,z)$ that assigns a single real number to each point in space is called:', '["A scalar field", "A vector field", "A tensor field", "A conservative field, regardless of its formula"]'::jsonb, 0, 'A scalar field assigns one real number (a scalar) to each point of space, e.g. a temperature or pressure distribution.', 'Scalar and Vector Fields', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A function $\vec F(x,y,z)$ that assigns a vector to each point in space is called:', '["A vector field", "A scalar field", "A harmonic field", "A bounded field"]'::jsonb, 0, 'A vector field assigns a vector (with both magnitude and direction) to each point of space, e.g. a velocity or force field.', 'Scalar and Vector Fields', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The gradient operator $\nabla$ (del), applied to a scalar field $\phi$, produces:', '["A vector field, $\\nabla\\phi = \\phi_x\\vec i + \\phi_y\\vec j + \\phi_z\\vec k$", "A scalar, equal to $\\phi_x+\\phi_y+\\phi_z$", "A vector field with only one nonzero component", "The zero vector, always"]'::jsonb, 0, 'The gradient of a scalar field is the vector of its partial derivatives: $\nabla\phi = \phi_x\vec i + \phi_y\vec j + \phi_z\vec k$.', 'The Gradient', false, 'second', 2),
