  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\phi$ at the point $(-1,-1,-1)$ for $\phi(x,y,z) = 2 x^{2} y + 2 x z^{2} + y z - 3$.', '["$(6, 1, 3)$", "$(7, 2, 4)$", "$(6, 0, 3)$", "$(-6, -1, -3)$"]'::jsonb, 0, '$\nabla\phi = (4 x y + 2 z^{2}, 2 x^{2} + z, 4 x z + y)$, so at $(-1,-1,-1)$ this is $(6, 1, 3)$.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\phi$ at the point $(0,-1,0)$ for $\phi(x,y,z) = x^{2} y + 4 x z^{2} + 3 y z$.', '["$(0, 0, -3)$", "$(1, 1, -2)$", "$(0, -1, -3)$", "$(0, 0, 3)$"]'::jsonb, 0, '$\nabla\phi = (2 x y + 4 z^{2}, x^{2} + 3 z, 8 x z + 3 y)$, so at $(0,-1,0)$ this is $(0, 0, -3)$.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\phi$ at the point $(2,1,0)$ for $\phi(x,y,z) = 2 x^{2} y + 2 x z^{2} + 3 y z$.', '["$(8, 8, 3)$", "$(9, 9, 4)$", "$(8, 7, 3)$", "$(-8, -8, -3)$"]'::jsonb, 0, '$\nabla\phi = (4 x y + 2 z^{2}, 2 x^{2} + 3 z, 4 x z + 3 y)$, so at $(2,1,0)$ this is $(8, 8, 3)$.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\phi$ at the point $(2,2,-2)$ for $\phi(x,y,z) = 4 x^{2} y + x z^{2} + 4 y z - 1$.', '["$(36, 8, 0)$", "$(37, 9, 1)$", "$(36, 7, 0)$", "$(-36, -8, 0)$"]'::jsonb, 0, '$\nabla\phi = (8 x y + z^{2}, 4 x^{2} + 4 z, 2 x z + 4 y)$, so at $(2,2,-2)$ this is $(36, 8, 0)$.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\phi$ at the point $(-1,2,0)$ for $\phi(x,y,z) = x^{2} y + 4 x z^{2} + y z - 3$.', '["$(-4, 1, 2)$", "$(-3, 2, 3)$", "$(-4, 0, 2)$", "$(4, -1, -2)$"]'::jsonb, 0, '$\nabla\phi = (2 x y + 4 z^{2}, x^{2} + z, 8 x z + y)$, so at $(-1,2,0)$ this is $(-4, 1, 2)$.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\phi$ at the point $(0,0,-2)$ for $\phi(x,y,z) = 3 x^{2} y + 4 x z^{2} + 2 y z - 3$.', '["$(16, -4, 0)$", "$(17, -3, 1)$", "$(16, -5, 0)$", "$(-16, 4, 0)$"]'::jsonb, 0, '$\nabla\phi = (6 x y + 4 z^{2}, 3 x^{2} + 2 z, 8 x z + 2 y)$, so at $(0,0,-2)$ this is $(16, -4, 0)$.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\phi$ at the point $(2,0,-2)$ for $\phi(x,y,z) = 4 x^{2} y + 4 x z^{2} + 3 y z + 3$.', '["$(16, 10, -32)$", "$(17, 11, -31)$", "$(16, 9, -32)$", "$(-16, -10, 32)$"]'::jsonb, 0, '$\nabla\phi = (8 x y + 4 z^{2}, 4 x^{2} + 3 z, 8 x z + 3 y)$, so at $(2,0,-2)$ this is $(16, 10, -32)$.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\phi$ at the point $(0,1,1)$ for $\phi(x,y,z) = 4 x^{2} y + 4 x z^{2} + y z + 2$.', '["$(4, 1, 1)$", "$(5, 2, 2)$", "$(4, 0, 1)$", "$(-4, -1, -1)$"]'::jsonb, 0, '$\nabla\phi = (8 x y + 4 z^{2}, 4 x^{2} + z, 8 x z + y)$, so at $(0,1,1)$ this is $(4, 1, 1)$.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The gradient vector $\nabla\phi$ at a point always points in the direction of:', '["The greatest rate of increase of $\\phi$ at that point", "The greatest rate of decrease of $\\phi$", "A direction tangent to the level surface through that point", "A fixed direction, independent of $\\phi$"]'::jsonb, 0, 'A standard property of the gradient: $\nabla\phi$ points in the direction in which $\phi$ increases most rapidly, and $|\nabla\phi|$ gives that maximum rate of increase.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The gradient vector $\nabla\phi$ at a point on a level surface $\phi = c$ is always:', '["Normal (perpendicular) to the level surface at that point", "Tangent to the level surface at that point", "Parallel to the $x$-axis", "Zero at every point of the level surface"]'::jsonb, 0, 'The gradient is normal to the level surface $\phi=c$ at every point -- this is the basis for finding tangent planes to surfaces defined implicitly.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the constants $a$ and $b$ so that the level surfaces of $\phi(x,y,z) = a x^2 + b y^2 - z$ are also level surfaces of $\psi(x,y,z) = x^2 + 4y^2 - 2z$ (i.e. so $\phi$ is proportional to $\psi$, matching the coefficient of $x^2$ to $1$ and $z$ to $-1/2$, so that $a=1$, $b=4/2=2$).', '["$a=1$, $b=2$", "$a=2$, $b=1$", "$a=1$, $b=4$", "$a=2$, $b=4$"]'::jsonb, 0, 'Matching $\phi = \frac{1}{2}\psi = x^2+2y^2-z$ against $ax^2+by^2-z$ gives $a=1$ and $b=2$.', 'The Gradient', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For a vector field $\vec F = P\vec i + Q\vec j + R\vec k$, the divergence $\nabla\cdot\vec F$ is defined as:', '["$P_x + Q_y + R_z$ (a scalar)", "$P_x\\vec i + Q_y\\vec j + R_z\\vec k$ (a vector)", "$PQR$", "$P_y + Q_x + R_z$"]'::jsonb, 0, 'The divergence of $\vec F=(P,Q,R)$ is the scalar $\nabla\cdot\vec F = P_x+Q_y+R_z$, measuring the net outward flux per unit volume.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\cdot\vec F$ (div $\vec F$) for $\vec F = (4 x y, 4 y z, 3 x z)$.', '["$3 x + 4 y + 4 z$", "$4 x + 4 y + 4 z$", "$4 x + 4 y + 3 z$", "$3 x + 3 y + 4 z$"]'::jsonb, 0, '$\nabla\cdot\vec F = \partial_x(4 x y) + \partial_y(4 y z) + \partial_z(3 x z) = 3 x + 4 y + 4 z$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\cdot\vec F$ (div $\vec F$) for $\vec F = (3 x y, 4 y z, x z)$.', '["$x + 3 y + 4 z$", "$2 x + 3 y + 4 z$", "$3 x + 4 y + z$", "$x + 2 y + 4 z$"]'::jsonb, 0, '$\nabla\cdot\vec F = \partial_x(3 x y) + \partial_y(4 y z) + \partial_z(x z) = x + 3 y + 4 z$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\cdot\vec F$ (div $\vec F$) for $\vec F = (4 x y, y z, x z)$.', '["$x + 4 y + z$", "$2 x + 4 y + z$", "$4 x + y + z$", "$x + 3 y + z$"]'::jsonb, 0, '$\nabla\cdot\vec F = \partial_x(4 x y) + \partial_y(y z) + \partial_z(x z) = x + 4 y + z$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\cdot\vec F$ (div $\vec F$) for $\vec F = (2 x y, 3 y z, x z)$.', '["$x + 2 y + 3 z$", "$2 x + 2 y + 3 z$", "$2 x + 3 y + z$", "$x + y + 3 z$"]'::jsonb, 0, '$\nabla\cdot\vec F = \partial_x(2 x y) + \partial_y(3 y z) + \partial_z(x z) = x + 2 y + 3 z$.', 'The Divergence of a Vector', false, 'second', 2),
