  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\cdot\vec F$ (div $\vec F$) for $\vec F = (4 x y, 2 y z, 3 x z)$.', '["$3 x + 4 y + 2 z$", "$4 x + 4 y + 2 z$", "$4 x + 2 y + 3 z$", "$3 x + 3 y + 2 z$"]'::jsonb, 0, '$\nabla\cdot\vec F = \partial_x(4 x y) + \partial_y(2 y z) + \partial_z(3 x z) = 3 x + 4 y + 2 z$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the value of $a$ so that $\nabla\cdot\vec F = 0$, where $\vec F = (ax, 2y, -4z)$.', '["$a = 2$", "$a = 3$", "$a = -2$", "$a = 0$"]'::jsonb, 0, '$\nabla\cdot\vec F = a + 2 + (-4) = 0 \Rightarrow a = 2$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the value of $a$ so that $\nabla\cdot\vec F = 0$, where $\vec F = (ax, 1y, -5z)$.', '["$a = 4$", "$a = 5$", "$a = -4$", "$a = 0$"]'::jsonb, 0, '$\nabla\cdot\vec F = a + 1 + (-5) = 0 \Rightarrow a = 4$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the value of $a$ so that $\nabla\cdot\vec F = 0$, where $\vec F = (ax, 1y, -3z)$.', '["$a = 2$", "$a = 3$", "$a = -2$", "$a = 0$"]'::jsonb, 0, '$\nabla\cdot\vec F = a + 1 + (-3) = 0 \Rightarrow a = 2$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the value of $a$ so that $\nabla\cdot\vec F = 0$, where $\vec F = (ax, 5y, -2z)$.', '["$a = -3$", "$a = -2$", "$a = 3$", "$a = 0$"]'::jsonb, 0, '$\nabla\cdot\vec F = a + 5 + (-2) = 0 \Rightarrow a = -3$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the value of $a$ so that $\nabla\cdot\vec F = 0$, where $\vec F = (ax, 4y, -5z)$.', '["$a = 1$", "$a = 2$", "$a = -1$", "$a = 0$"]'::jsonb, 0, '$\nabla\cdot\vec F = a + 4 + (-5) = 0 \Rightarrow a = 1$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the value of $a$ so that $\nabla\cdot\vec F = 0$, where $\vec F = (ax, 3y, -1z)$.', '["$a = -2$", "$a = -1$", "$a = 2$", "$a = 0$"]'::jsonb, 0, '$\nabla\cdot\vec F = a + 3 + (-1) = 0 \Rightarrow a = -2$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the value of $a$ so that $\nabla\cdot\vec F = 0$, where $\vec F = (ax, 4y, -6z)$.', '["$a = 2$", "$a = 3$", "$a = -2$", "$a = 0$"]'::jsonb, 0, '$\nabla\cdot\vec F = a + 4 + (-6) = 0 \Rightarrow a = 2$.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec W$ is a constant vector field and $\vec r = x\vec i + y\vec j + z\vec k$ is the position vector, what is $\nabla\cdot(\vec W \times \vec r)$?', '["$0$, for every constant vector $\\vec W$", "$3$", "$|\\vec W|$", "$\\vec W$"]'::jsonb, 0, 'Writing $\vec W=(w_1,w_2,w_3)$ (constants) and expanding $\vec W\times\vec r$ componentwise, direct computation shows every term in $\nabla\cdot(\vec W\times\vec r)$ cancels, giving $0$ identically -- the cross product of a constant vector with the position vector is always divergence-free.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A vector field $\vec F$ satisfying $\nabla\cdot\vec F = 0$ throughout a region is called:', '["Solenoidal (divergence-free)", "Irrotational", "Conservative", "Harmonic"]'::jsonb, 0, 'A vector field with zero divergence everywhere is called solenoidal, meaning it has no net ''sources'' or ''sinks''.', 'The Divergence of a Vector', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For a vector field $\vec F = P\vec i + Q\vec j + R\vec k$, the curl $\nabla\times\vec F$ is defined as:', '["$(R_y-Q_z)\\vec i + (P_z-R_x)\\vec j + (Q_x-P_y)\\vec k$", "$P_x\\vec i + Q_y\\vec j + R_z\\vec k$", "$PQR$, a scalar", "$(P_x+Q_y+R_z)$, a scalar"]'::jsonb, 0, 'The curl is computed as the formal determinant $\nabla\times\vec F = (R_y-Q_z)\vec i + (P_z-R_x)\vec j + (Q_x-P_y)\vec k$.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\times\vec F$ (curl $\vec F$) for $\vec F = (4 x y, 3 y z, 3 x z)$.', '["$(- 3 y, - 3 z, - 4 x)$", "$(- 3 z, - 3 y, - 4 x)$", "$(x - 3 y, - 3 z, - 4 x)$", "$(3 y, 3 z, 4 x)$"]'::jsonb, 0, 'With $P=4 x y, Q=3 y z, R=3 x z$: curl $=(R_y-Q_z, P_z-R_x, Q_x-P_y) = (- 3 y, - 3 z, - 4 x)$.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\times\vec F$ (curl $\vec F$) for $\vec F = (2 x y, 4 y z, 4 x z)$.', '["$(- 4 y, - 4 z, - 2 x)$", "$(- 4 z, - 4 y, - 2 x)$", "$(x - 4 y, - 4 z, - 2 x)$", "$(4 y, 4 z, 2 x)$"]'::jsonb, 0, 'With $P=2 x y, Q=4 y z, R=4 x z$: curl $=(R_y-Q_z, P_z-R_x, Q_x-P_y) = (- 4 y, - 4 z, - 2 x)$.', 'The Curl of a Vector Field', false, 'second', 2),
