  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\times\vec F$ (curl $\vec F$) for $\vec F = (4 x y, 3 y z, 2 x z)$.', '["$(- 3 y, - 2 z, - 4 x)$", "$(- 2 z, - 3 y, - 4 x)$", "$(x - 3 y, - 2 z, - 4 x)$", "$(3 y, 2 z, 4 x)$"]'::jsonb, 0, 'With $P=4 x y, Q=3 y z, R=2 x z$: curl $=(R_y-Q_z, P_z-R_x, Q_x-P_y) = (- 3 y, - 2 z, - 4 x)$.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\times\vec F$ (curl $\vec F$) for $\vec F = (2 x y, 3 y z, x z)$.', '["$(- 3 y, - z, - 2 x)$", "$(- z, - 3 y, - 2 x)$", "$(x - 3 y, - z, - 2 x)$", "$(3 y, z, 2 x)$"]'::jsonb, 0, 'With $P=2 x y, Q=3 y z, R=x z$: curl $=(R_y-Q_z, P_z-R_x, Q_x-P_y) = (- 3 y, - z, - 2 x)$.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\times\vec F$ (curl $\vec F$) for $\vec F = (3 x y, y z, 3 x z)$.', '["$(- y, - 3 z, - 3 x)$", "$(- 3 z, - y, - 3 x)$", "$(x - y, - 3 z, - 3 x)$", "$(y, 3 z, 3 x)$"]'::jsonb, 0, 'With $P=3 x y, Q=y z, R=3 x z$: curl $=(R_y-Q_z, P_z-R_x, Q_x-P_y) = (- y, - 3 z, - 3 x)$.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\times\vec F$ (curl $\vec F$) for $\vec F = (3 x y, 4 y z, 2 x z)$.', '["$(- 4 y, - 2 z, - 3 x)$", "$(- 2 z, - 4 y, - 3 x)$", "$(x - 4 y, - 2 z, - 3 x)$", "$(4 y, 2 z, 3 x)$"]'::jsonb, 0, 'With $P=3 x y, Q=4 y z, R=2 x z$: curl $=(R_y-Q_z, P_z-R_x, Q_x-P_y) = (- 4 y, - 2 z, - 3 x)$.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\times\vec F$ (curl $\vec F$) for $\vec F = (3 x y, 4 y z, 4 x z)$.', '["$(- 4 y, - 4 z, - 3 x)$", "$(- 4 z, - 4 y, - 3 x)$", "$(x - 4 y, - 4 z, - 3 x)$", "$(4 y, 4 z, 3 x)$"]'::jsonb, 0, 'With $P=3 x y, Q=4 y z, R=4 x z$: curl $=(R_y-Q_z, P_z-R_x, Q_x-P_y) = (- 4 y, - 4 z, - 3 x)$.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\nabla\times\vec F$ (curl $\vec F$) for $\vec F = (3 x y, y z, 4 x z)$.', '["$(- y, - 4 z, - 3 x)$", "$(- 4 z, - y, - 3 x)$", "$(x - y, - 4 z, - 3 x)$", "$(y, 4 z, 3 x)$"]'::jsonb, 0, 'With $P=3 x y, Q=y z, R=4 x z$: curl $=(R_y-Q_z, P_z-R_x, Q_x-P_y) = (- y, - 4 z, - 3 x)$.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A vector field $\vec F$ satisfying $\nabla\times\vec F = \vec 0$ throughout a (simply connected) region is called:', '["Irrotational (curl-free)", "Solenoidal", "Harmonic", "Analytic"]'::jsonb, 0, 'A vector field with zero curl everywhere is called irrotational -- it has no local rotation or ''swirl''.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For any scalar field $\phi$ with continuous second partial derivatives, what is $\nabla\times(\nabla\phi)$ (the curl of the gradient)?', '["$\\vec 0$, always -- the gradient of a scalar field is always irrotational", "$\\nabla\\phi$ itself", "A vector depending on $\\phi$, generally nonzero", "$\\nabla^2\\phi$"]'::jsonb, 0, 'Computing $\nabla\times\nabla\phi$ componentwise gives terms like $\phi_{yz}-\phi_{zy}$, which vanish by equality of mixed partials -- so $\nabla\times\nabla\phi=\vec 0$ identically, meaning every gradient field is conservative (irrotational).', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For any vector field $\vec F$ with continuous second partial derivatives, what is $\nabla\cdot(\nabla\times\vec F)$ (the divergence of the curl)?', '["$0$, always -- the curl of any vector field is always divergence-free (solenoidal)", "$\\nabla^2 F$", "$|\\vec F|$", "A scalar depending on $\\vec F$, generally nonzero"]'::jsonb, 0, 'Expanding $\nabla\cdot(\nabla\times\vec F)$ produces a sum of mixed second partial derivatives that cancel in pairs by equality of mixed partials, giving $0$ identically -- every curl field is automatically solenoidal.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $\vec F = (ayz, 1xz, 3xy)$, find the value of $a$ (in terms of the given numbers) that makes $\vec F$ irrotational ($\nabla\times\vec F=\vec 0$), given that the other two coefficients are both 1.', '["$a = 1$", "$a = 2$", "$a = -1$", "$a = 0$"]'::jsonb, 0, '$\nabla\times\vec F = ((c-b)x, (a-c)y, (b-a)z)$; with $b=c=1$, this vanishes identically only when $a=b=1$ too, so all three coefficients must be equal.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $\vec F = (ayz, 4xz, 2xy)$, find the value of $a$ (in terms of the given numbers) that makes $\vec F$ irrotational ($\nabla\times\vec F=\vec 0$), given that the other two coefficients are both 4.', '["$a = 4$", "$a = 5$", "$a = -4$", "$a = 0$"]'::jsonb, 0, '$\nabla\times\vec F = ((c-b)x, (a-c)y, (b-a)z)$; with $b=c=4$, this vanishes identically only when $a=b=4$ too, so all three coefficients must be equal.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $\vec F = (ayz, 4xz, 3xy)$, find the value of $a$ (in terms of the given numbers) that makes $\vec F$ irrotational ($\nabla\times\vec F=\vec 0$), given that the other two coefficients are both 4.', '["$a = 4$", "$a = 5$", "$a = -4$", "$a = 0$"]'::jsonb, 0, '$\nabla\times\vec F = ((c-b)x, (a-c)y, (b-a)z)$; with $b=c=4$, this vanishes identically only when $a=b=4$ too, so all three coefficients must be equal.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $\vec F = (ayz, 3xz, 5xy)$, find the value of $a$ (in terms of the given numbers) that makes $\vec F$ irrotational ($\nabla\times\vec F=\vec 0$), given that the other two coefficients are both 3.', '["$a = 3$", "$a = 4$", "$a = -3$", "$a = 0$"]'::jsonb, 0, '$\nabla\times\vec F = ((c-b)x, (a-c)y, (b-a)z)$; with $b=c=3$, this vanishes identically only when $a=b=3$ too, so all three coefficients must be equal.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $\vec F = (ayz, 1xz, 4xy)$, find the value of $a$ (in terms of the given numbers) that makes $\vec F$ irrotational ($\nabla\times\vec F=\vec 0$), given that the other two coefficients are both 1.', '["$a = 1$", "$a = 2$", "$a = -1$", "$a = 0$"]'::jsonb, 0, '$\nabla\times\vec F = ((c-b)x, (a-c)y, (b-a)z)$; with $b=c=1$, this vanishes identically only when $a=b=1$ too, so all three coefficients must be equal.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $\vec F = (ayz, 2xz, 4xy)$, find the value of $a$ (in terms of the given numbers) that makes $\vec F$ irrotational ($\nabla\times\vec F=\vec 0$), given that the other two coefficients are both 2.', '["$a = 2$", "$a = 3$", "$a = -2$", "$a = 0$"]'::jsonb, 0, '$\nabla\times\vec F = ((c-b)x, (a-c)y, (b-a)z)$; with $b=c=2$, this vanishes identically only when $a=b=2$ too, so all three coefficients must be equal.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $\vec F = (ayz, 5xz, 2xy)$, find the value of $a$ (in terms of the given numbers) that makes $\vec F$ irrotational ($\nabla\times\vec F=\vec 0$), given that the other two coefficients are both 5.', '["$a = 5$", "$a = 6$", "$a = -5$", "$a = 0$"]'::jsonb, 0, '$\nabla\times\vec F = ((c-b)x, (a-c)y, (b-a)z)$; with $b=c=5$, this vanishes identically only when $a=b=5$ too, so all three coefficients must be equal.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $\vec F = (ayz, 4xz, 5xy)$, find the value of $a$ (in terms of the given numbers) that makes $\vec F$ irrotational ($\nabla\times\vec F=\vec 0$), given that the other two coefficients are both 4.', '["$a = 4$", "$a = 5$", "$a = -4$", "$a = 0$"]'::jsonb, 0, '$\nabla\times\vec F = ((c-b)x, (a-c)y, (b-a)z)$; with $b=c=4$, this vanishes identically only when $a=b=4$ too, so all three coefficients must be equal.', 'The Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $\vec r(t) = f(t)\vec i + g(t)\vec j + h(t)\vec k$, the indefinite integral $\int \vec r(t)\, dt$ is computed by:', '["Integrating each component separately: $\\int f\\,dt\\;\\vec i + \\int g\\,dt\\;\\vec j + \\int h\\,dt\\;\\vec k$, plus a constant vector $\\vec C$", "Integrating only the $\\vec i$ component", "Multiplying $f, g, h$ together and integrating the product", "Taking the derivative of each component instead"]'::jsonb, 0, 'A vector function is integrated componentwise, just as it is differentiated componentwise, with an arbitrary constant VECTOR $\vec C$ of integration.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (3 t^{2} + 4, 5 t - 4)$.', '["$(t^{3} + 4 t, \\frac{5 t^{2}}{2} - 4 t) + \\vec C$", "$(t^{3} + 5 t, \\frac{5 t^{2}}{2} - 4 t) + \\vec C$", "$(t^{3} + 4 t, \\frac{5 t^{2}}{2} - 5 t) + \\vec C$", "$(6 t, 5) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 3 t^{2} + 4\,dt = t^{3} + 4 t$ and $\int 5 t - 4\,dt = \frac{5 t^{2}}{2} - 4 t$, giving $(t^{3} + 4 t, \frac{5 t^{2}}{2} - 4 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (3 t^{2} - 2, 2 t)$.', '["$(t^{3} - 2 t, t^{2}) + \\vec C$", "$(t^{3} - t, t^{2}) + \\vec C$", "$(t^{3} - 2 t, t^{2} - t) + \\vec C$", "$(6 t, 2) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 3 t^{2} - 2\,dt = t^{3} - 2 t$ and $\int 2 t\,dt = t^{2}$, giving $(t^{3} - 2 t, t^{2}) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (t^{2} - 1, 5 t - 4)$.', '["$(\\frac{t^{3}}{3} - t, \\frac{5 t^{2}}{2} - 4 t) + \\vec C$", "$(\\frac{t^{3}}{3}, \\frac{5 t^{2}}{2} - 4 t) + \\vec C$", "$(\\frac{t^{3}}{3} - t, \\frac{5 t^{2}}{2} - 5 t) + \\vec C$", "$(2 t, 5) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int t^{2} - 1\,dt = \frac{t^{3}}{3} - t$ and $\int 5 t - 4\,dt = \frac{5 t^{2}}{2} - 4 t$, giving $(\frac{t^{3}}{3} - t, \frac{5 t^{2}}{2} - 4 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (5 t^{2} - 1, 5 t - 4)$.', '["$(\\frac{5 t^{3}}{3} - t, \\frac{5 t^{2}}{2} - 4 t) + \\vec C$", "$(\\frac{5 t^{3}}{3}, \\frac{5 t^{2}}{2} - 4 t) + \\vec C$", "$(\\frac{5 t^{3}}{3} - t, \\frac{5 t^{2}}{2} - 5 t) + \\vec C$", "$(10 t, 5) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 5 t^{2} - 1\,dt = \frac{5 t^{3}}{3} - t$ and $\int 5 t - 4\,dt = \frac{5 t^{2}}{2} - 4 t$, giving $(\frac{5 t^{3}}{3} - t, \frac{5 t^{2}}{2} - 4 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (5 t^{2} + 1, 4 t - 2)$.', '["$(\\frac{5 t^{3}}{3} + t, 2 t^{2} - 2 t) + \\vec C$", "$(\\frac{5 t^{3}}{3} + 2 t, 2 t^{2} - 2 t) + \\vec C$", "$(\\frac{5 t^{3}}{3} + t, 2 t^{2} - 3 t) + \\vec C$", "$(10 t, 4) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 5 t^{2} + 1\,dt = \frac{5 t^{3}}{3} + t$ and $\int 4 t - 2\,dt = 2 t^{2} - 2 t$, giving $(\frac{5 t^{3}}{3} + t, 2 t^{2} - 2 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (3 t^{2} - 2, t + 1)$.', '["$(t^{3} - 2 t, \\frac{t^{2}}{2} + t) + \\vec C$", "$(t^{3} - t, \\frac{t^{2}}{2} + t) + \\vec C$", "$(t^{3} - 2 t, \\frac{t^{2}}{2}) + \\vec C$", "$(6 t, 1) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 3 t^{2} - 2\,dt = t^{3} - 2 t$ and $\int t + 1\,dt = \frac{t^{2}}{2} + t$, giving $(t^{3} - 2 t, \frac{t^{2}}{2} + t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (5 t^{2} - 4, 4 t - 1)$.', '["$(\\frac{5 t^{3}}{3} - 4 t, 2 t^{2} - t) + \\vec C$", "$(\\frac{5 t^{3}}{3} - 3 t, 2 t^{2} - t) + \\vec C$", "$(\\frac{5 t^{3}}{3} - 4 t, 2 t^{2} - 2 t) + \\vec C$", "$(10 t, 4) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 5 t^{2} - 4\,dt = \frac{5 t^{3}}{3} - 4 t$ and $\int 4 t - 1\,dt = 2 t^{2} - t$, giving $(\frac{5 t^{3}}{3} - 4 t, 2 t^{2} - t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (2 t^{2} + 1, 4 t + 3)$.', '["$(\\frac{2 t^{3}}{3} + t, 2 t^{2} + 3 t) + \\vec C$", "$(\\frac{2 t^{3}}{3} + 2 t, 2 t^{2} + 3 t) + \\vec C$", "$(\\frac{2 t^{3}}{3} + t, 2 t^{2} + 2 t) + \\vec C$", "$(4 t, 4) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 2 t^{2} + 1\,dt = \frac{2 t^{3}}{3} + t$ and $\int 4 t + 3\,dt = 2 t^{2} + 3 t$, giving $(\frac{2 t^{3}}{3} + t, 2 t^{2} + 3 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (t^{2} - 4, 2 t - 2)$.', '["$(\\frac{t^{3}}{3} - 4 t, t^{2} - 2 t) + \\vec C$", "$(\\frac{t^{3}}{3} - 3 t, t^{2} - 2 t) + \\vec C$", "$(\\frac{t^{3}}{3} - 4 t, t^{2} - 3 t) + \\vec C$", "$(2 t, 2) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int t^{2} - 4\,dt = \frac{t^{3}}{3} - 4 t$ and $\int 2 t - 2\,dt = t^{2} - 2 t$, giving $(\frac{t^{3}}{3} - 4 t, t^{2} - 2 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (2 t^{2} - 1, 5 t + 1)$.', '["$(\\frac{2 t^{3}}{3} - t, \\frac{5 t^{2}}{2} + t) + \\vec C$", "$(\\frac{2 t^{3}}{3}, \\frac{5 t^{2}}{2} + t) + \\vec C$", "$(\\frac{2 t^{3}}{3} - t, \\frac{5 t^{2}}{2}) + \\vec C$", "$(4 t, 5) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 2 t^{2} - 1\,dt = \frac{2 t^{3}}{3} - t$ and $\int 5 t + 1\,dt = \frac{5 t^{2}}{2} + t$, giving $(\frac{2 t^{3}}{3} - t, \frac{5 t^{2}}{2} + t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (3 t^{2} - 4, 3 t + 1)$.', '["$(t^{3} - 4 t, \\frac{3 t^{2}}{2} + t) + \\vec C$", "$(t^{3} - 3 t, \\frac{3 t^{2}}{2} + t) + \\vec C$", "$(t^{3} - 4 t, \\frac{3 t^{2}}{2}) + \\vec C$", "$(6 t, 3) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 3 t^{2} - 4\,dt = t^{3} - 4 t$ and $\int 3 t + 1\,dt = \frac{3 t^{2}}{2} + t$, giving $(t^{3} - 4 t, \frac{3 t^{2}}{2} + t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (2 t^{2} + 2, t - 3)$.', '["$(\\frac{2 t^{3}}{3} + 2 t, \\frac{t^{2}}{2} - 3 t) + \\vec C$", "$(\\frac{2 t^{3}}{3} + 3 t, \\frac{t^{2}}{2} - 3 t) + \\vec C$", "$(\\frac{2 t^{3}}{3} + 2 t, \\frac{t^{2}}{2} - 4 t) + \\vec C$", "$(4 t, 1) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 2 t^{2} + 2\,dt = \frac{2 t^{3}}{3} + 2 t$ and $\int t - 3\,dt = \frac{t^{2}}{2} - 3 t$, giving $(\frac{2 t^{3}}{3} + 2 t, \frac{t^{2}}{2} - 3 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (t^{2} - 1, t)$.', '["$(\\frac{t^{3}}{3} - t, \\frac{t^{2}}{2}) + \\vec C$", "$(\\frac{t^{3}}{3}, \\frac{t^{2}}{2}) + \\vec C$", "$(\\frac{t^{3}}{3} - t, \\frac{t^{2}}{2} - t) + \\vec C$", "$(2 t, 1) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int t^{2} - 1\,dt = \frac{t^{3}}{3} - t$ and $\int t\,dt = \frac{t^{2}}{2}$, giving $(\frac{t^{3}}{3} - t, \frac{t^{2}}{2}) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (2 t^{2} + 2, 4 t + 3)$.', '["$(\\frac{2 t^{3}}{3} + 2 t, 2 t^{2} + 3 t) + \\vec C$", "$(\\frac{2 t^{3}}{3} + 3 t, 2 t^{2} + 3 t) + \\vec C$", "$(\\frac{2 t^{3}}{3} + 2 t, 2 t^{2} + 2 t) + \\vec C$", "$(4 t, 4) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 2 t^{2} + 2\,dt = \frac{2 t^{3}}{3} + 2 t$ and $\int 4 t + 3\,dt = 2 t^{2} + 3 t$, giving $(\frac{2 t^{3}}{3} + 2 t, 2 t^{2} + 3 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (5 t^{2} + 1, 3 t - 3)$.', '["$(\\frac{5 t^{3}}{3} + t, \\frac{3 t^{2}}{2} - 3 t) + \\vec C$", "$(\\frac{5 t^{3}}{3} + 2 t, \\frac{3 t^{2}}{2} - 3 t) + \\vec C$", "$(\\frac{5 t^{3}}{3} + t, \\frac{3 t^{2}}{2} - 4 t) + \\vec C$", "$(10 t, 3) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 5 t^{2} + 1\,dt = \frac{5 t^{3}}{3} + t$ and $\int 3 t - 3\,dt = \frac{3 t^{2}}{2} - 3 t$, giving $(\frac{5 t^{3}}{3} + t, \frac{3 t^{2}}{2} - 3 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (2 t^{2}, 5 t - 1)$.', '["$(\\frac{2 t^{3}}{3}, \\frac{5 t^{2}}{2} - t) + \\vec C$", "$(\\frac{2 t^{3}}{3} + t, \\frac{5 t^{2}}{2} - t) + \\vec C$", "$(\\frac{2 t^{3}}{3}, \\frac{5 t^{2}}{2} - 2 t) + \\vec C$", "$(4 t, 5) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 2 t^{2}\,dt = \frac{2 t^{3}}{3}$ and $\int 5 t - 1\,dt = \frac{5 t^{2}}{2} - t$, giving $(\frac{2 t^{3}}{3}, \frac{5 t^{2}}{2} - t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (2 t^{2} + 3, 4 t + 4)$.', '["$(\\frac{2 t^{3}}{3} + 3 t, 2 t^{2} + 4 t) + \\vec C$", "$(\\frac{2 t^{3}}{3} + 4 t, 2 t^{2} + 4 t) + \\vec C$", "$(\\frac{2 t^{3}}{3} + 3 t, 2 t^{2} + 3 t) + \\vec C$", "$(4 t, 4) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 2 t^{2} + 3\,dt = \frac{2 t^{3}}{3} + 3 t$ and $\int 4 t + 4\,dt = 2 t^{2} + 4 t$, giving $(\frac{2 t^{3}}{3} + 3 t, 2 t^{2} + 4 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (3 t^{2}, t)$.', '["$(t^{3}, \\frac{t^{2}}{2}) + \\vec C$", "$(t^{3} + t, \\frac{t^{2}}{2}) + \\vec C$", "$(t^{3}, \\frac{t^{2}}{2} - t) + \\vec C$", "$(6 t, 1) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 3 t^{2}\,dt = t^{3}$ and $\int t\,dt = \frac{t^{2}}{2}$, giving $(t^{3}, \frac{t^{2}}{2}) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (t^{2} - 4, 2 t - 1)$.', '["$(\\frac{t^{3}}{3} - 4 t, t^{2} - t) + \\vec C$", "$(\\frac{t^{3}}{3} - 3 t, t^{2} - t) + \\vec C$", "$(\\frac{t^{3}}{3} - 4 t, t^{2} - 2 t) + \\vec C$", "$(2 t, 2) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int t^{2} - 4\,dt = \frac{t^{3}}{3} - 4 t$ and $\int 2 t - 1\,dt = t^{2} - t$, giving $(\frac{t^{3}}{3} - 4 t, t^{2} - t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\int \vec r(t)\, dt$ for $\vec r(t) = (4 t^{2} + 1, 5 t + 4)$.', '["$(\\frac{4 t^{3}}{3} + t, \\frac{5 t^{2}}{2} + 4 t) + \\vec C$", "$(\\frac{4 t^{3}}{3} + 2 t, \\frac{5 t^{2}}{2} + 4 t) + \\vec C$", "$(\\frac{4 t^{3}}{3} + t, \\frac{5 t^{2}}{2} + 3 t) + \\vec C$", "$(8 t, 5) + \\vec C$"]'::jsonb, 0, 'Integrating each component: $\int 4 t^{2} + 1\,dt = \frac{4 t^{3}}{3} + t$ and $\int 5 t + 4\,dt = \frac{5 t^{2}}{2} + 4 t$, giving $(\frac{4 t^{3}}{3} + t, \frac{5 t^{2}}{2} + 4 t) + \vec C$.', 'Integration of Vector Functions', false, 'second', 2),
