  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_{0}^{1} \vec r(t)\, dt$ for $\vec r(t) = (3 t - 2, 2 t^{2})$.', '["$(-1/2, 2/3)$", "$(1/2, 2/3)$", "$(-1/2, -1/3)$", "$(1, 2)$"]'::jsonb, 0, '$\int_0^{1} (3 t - 2)\,dt = -1/2$ and $\int_0^{1} (2 t^{2})\,dt = 2/3$, giving $(-1/2, 2/3)$.', 'Integration of Vector Functions', false, 'second', 2),
