  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_{0}^{2} \vec r(t)\, dt$ for $\vec r(t) = (3 t - 3, 2 t^{2})$.', '["$(0, 16/3)$", "$(1, 16/3)$", "$(0, 13/3)$", "$(3, 8)$"]'::jsonb, 0, '$\int_0^{2} (3 t - 3)\,dt = 0$ and $\int_0^{2} (2 t^{2})\,dt = 16/3$, giving $(0, 16/3)$.', 'Integration of Vector Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A line integral of a scalar function $f(x,y,z)$ along a curve $C$ parametrized by $\vec r(t)$, $a\leq t\leq b$, is computed as:', '["$\\displaystyle\\int_a^b f(\\vec r(t))\\,|\\vec r''(t)|\\, dt$", "$\\displaystyle\\int_a^b f(\\vec r(t))\\, dt$, with no adjustment for speed", "$\\displaystyle\\int_a^b \\vec r(t)\\, dt$", "$f(\\vec r(b)) - f(\\vec r(a))$"]'::jsonb, 0, 'A scalar line integral weights $f$ along the curve by the speed $|\vec r''(t)|$: $\int_C f\,ds = \int_a^b f(\vec r(t))|\vec r''(t)|\,dt$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate the line integral $\displaystyle\int_C (x+y)\, ds$ where $C$ is the straight segment $\vec r(t) = (2t, 1t)$ for $0 \leq t \leq 3$.', '["$\\frac{27 \\sqrt{5}}{2}$", "$1 + \\frac{27 \\sqrt{5}}{2}$", "$27 \\sqrt{5}$", "$0$"]'::jsonb, 0, 'On $C$: $x+y = 3t$ and $ds = |\vec r''(t)|\,dt = \sqrt{2^2+1^2}\,dt = \sqrt{5}\,dt$, so the integral is $\int_0^{3} 3t \cdot \sqrt{5}\,dt = \frac{27 \sqrt{5}}{2}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate the line integral $\displaystyle\int_C (x+y)\, ds$ where $C$ is the straight segment $\vec r(t) = (2t, 3t)$ for $0 \leq t \leq 1$.', '["$\\frac{5 \\sqrt{13}}{2}$", "$1 + \\frac{5 \\sqrt{13}}{2}$", "$5 \\sqrt{13}$", "$0$"]'::jsonb, 0, 'On $C$: $x+y = 5t$ and $ds = |\vec r''(t)|\,dt = \sqrt{2^2+3^2}\,dt = \sqrt{13}\,dt$, so the integral is $\int_0^{1} 5t \cdot \sqrt{13}\,dt = \frac{5 \sqrt{13}}{2}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate the line integral $\displaystyle\int_C (x+y)\, ds$ where $C$ is the straight segment $\vec r(t) = (2t, 2t)$ for $0 \leq t \leq 3$.', '["$36 \\sqrt{2}$", "$1 + 36 \\sqrt{2}$", "$72 \\sqrt{2}$", "$0$"]'::jsonb, 0, 'On $C$: $x+y = 4t$ and $ds = |\vec r''(t)|\,dt = \sqrt{2^2+2^2}\,dt = 2 \sqrt{2}\,dt$, so the integral is $\int_0^{3} 4t \cdot 2 \sqrt{2}\,dt = 36 \sqrt{2}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate the line integral $\displaystyle\int_C (x+y)\, ds$ where $C$ is the straight segment $\vec r(t) = (1t, 2t)$ for $0 \leq t \leq 2$.', '["$6 \\sqrt{5}$", "$1 + 6 \\sqrt{5}$", "$12 \\sqrt{5}$", "$0$"]'::jsonb, 0, 'On $C$: $x+y = 3t$ and $ds = |\vec r''(t)|\,dt = \sqrt{1^2+2^2}\,dt = \sqrt{5}\,dt$, so the integral is $\int_0^{2} 3t \cdot \sqrt{5}\,dt = 6 \sqrt{5}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate the line integral $\displaystyle\int_C (x+y)\, ds$ where $C$ is the straight segment $\vec r(t) = (3t, 3t)$ for $0 \leq t \leq 1$.', '["$9 \\sqrt{2}$", "$1 + 9 \\sqrt{2}$", "$18 \\sqrt{2}$", "$0$"]'::jsonb, 0, 'On $C$: $x+y = 6t$ and $ds = |\vec r''(t)|\,dt = \sqrt{3^2+3^2}\,dt = 3 \sqrt{2}\,dt$, so the integral is $\int_0^{1} 6t \cdot 3 \sqrt{2}\,dt = 9 \sqrt{2}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate the line integral $\displaystyle\int_C (x+y)\, ds$ where $C$ is the straight segment $\vec r(t) = (2t, 1t)$ for $0 \leq t \leq 1$.', '["$\\frac{3 \\sqrt{5}}{2}$", "$1 + \\frac{3 \\sqrt{5}}{2}$", "$3 \\sqrt{5}$", "$0$"]'::jsonb, 0, 'On $C$: $x+y = 3t$ and $ds = |\vec r''(t)|\,dt = \sqrt{2^2+1^2}\,dt = \sqrt{5}\,dt$, so the integral is $\int_0^{1} 3t \cdot \sqrt{5}\,dt = \frac{3 \sqrt{5}}{2}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate the line integral $\displaystyle\int_C (x+y)\, ds$ where $C$ is the straight segment $\vec r(t) = (2t, 2t)$ for $0 \leq t \leq 1$.', '["$4 \\sqrt{2}$", "$1 + 4 \\sqrt{2}$", "$8 \\sqrt{2}$", "$0$"]'::jsonb, 0, 'On $C$: $x+y = 4t$ and $ds = |\vec r''(t)|\,dt = \sqrt{2^2+2^2}\,dt = 2 \sqrt{2}\,dt$, so the integral is $\int_0^{1} 4t \cdot 2 \sqrt{2}\,dt = 4 \sqrt{2}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate the line integral $\displaystyle\int_C (x+y)\, ds$ where $C$ is the straight segment $\vec r(t) = (2t, 3t)$ for $0 \leq t \leq 3$.', '["$\\frac{45 \\sqrt{13}}{2}$", "$1 + \\frac{45 \\sqrt{13}}{2}$", "$45 \\sqrt{13}$", "$0$"]'::jsonb, 0, 'On $C$: $x+y = 5t$ and $ds = |\vec r''(t)|\,dt = \sqrt{2^2+3^2}\,dt = \sqrt{13}\,dt$, so the integral is $\int_0^{3} 5t \cdot \sqrt{13}\,dt = \frac{45 \sqrt{13}}{2}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate the line integral $\displaystyle\int_C (x+y)\, ds$ where $C$ is the straight segment $\vec r(t) = (1t, 3t)$ for $0 \leq t \leq 1$.', '["$2 \\sqrt{10}$", "$1 + 2 \\sqrt{10}$", "$4 \\sqrt{10}$", "$0$"]'::jsonb, 0, 'On $C$: $x+y = 4t$ and $ds = |\vec r''(t)|\,dt = \sqrt{1^2+3^2}\,dt = \sqrt{10}\,dt$, so the integral is $\int_0^{1} 4t \cdot \sqrt{10}\,dt = 2 \sqrt{10}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The line integral (work integral) of a vector field $\vec F$ along a curve $C$ parametrized by $\vec r(t)$, $a\leq t\leq b$, is defined as:', '["$\\displaystyle\\int_C \\vec F \\cdot d\\vec r = \\int_a^b \\vec F(\\vec r(t))\\cdot \\vec r''(t)\\, dt$", "$\\displaystyle\\int_a^b |\\vec F(\\vec r(t))|\\, dt$", "$\\displaystyle\\int_a^b \\vec F(\\vec r(t))\\, dt$, without the dot product", "$\\vec F(\\vec r(b)) \\cdot \\vec F(\\vec r(a))$"]'::jsonb, 0, 'The work done by $\vec F$ along $C$ is $\int_C \vec F\cdot d\vec r = \int_a^b \vec F(\vec r(t)) \cdot \vec r''(t)\, dt$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 3y)$ and $C$ is the path $\vec r(t) = (t, 3t^2)$ for $0 \leq t \leq 1$.', '["$\\frac{57}{4}$", "$\\frac{61}{4}$", "$\\frac{53}{4}$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=3t^2$, so $\vec F(\vec r(t)) = (3 t^{3}, 9 t^{2})$ and $\vec r''(t) = (1, 6 t)$. Dotting and integrating from $0$ to $1$ gives $\frac{57}{4}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 1y)$ and $C$ is the path $\vec r(t) = (t, 2t^2)$ for $0 \leq t \leq 2$.', '["$40$", "$41$", "$39$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=2t^2$, so $\vec F(\vec r(t)) = (2 t^{3}, 2 t^{2})$ and $\vec r''(t) = (1, 4 t)$. Dotting and integrating from $0$ to $2$ gives $40$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 1y)$ and $C$ is the path $\vec r(t) = (t, 1t^2)$ for $0 \leq t \leq 2$.', '["$12$", "$13$", "$11$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=1t^2$, so $\vec F(\vec r(t)) = (t^{3}, t^{2})$ and $\vec r''(t) = (1, 2 t)$. Dotting and integrating from $0$ to $2$ gives $12$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 2y)$ and $C$ is the path $\vec r(t) = (t, 1t^2)$ for $0 \leq t \leq 2$.', '["$20$", "$21$", "$19$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=1t^2$, so $\vec F(\vec r(t)) = (t^{3}, 2 t^{2})$ and $\vec r''(t) = (1, 2 t)$. Dotting and integrating from $0$ to $2$ gives $20$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 2y)$ and $C$ is the path $\vec r(t) = (t, 3t^2)$ for $0 \leq t \leq 2$.', '["$156$", "$157$", "$155$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=3t^2$, so $\vec F(\vec r(t)) = (3 t^{3}, 6 t^{2})$ and $\vec r''(t) = (1, 6 t)$. Dotting and integrating from $0$ to $2$ gives $156$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 3y)$ and $C$ is the path $\vec r(t) = (t, 1t^2)$ for $0 \leq t \leq 2$.', '["$28$", "$29$", "$27$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=1t^2$, so $\vec F(\vec r(t)) = (t^{3}, 3 t^{2})$ and $\vec r''(t) = (1, 2 t)$. Dotting and integrating from $0$ to $2$ gives $28$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 2y)$ and $C$ is the path $\vec r(t) = (t, 3t^2)$ for $0 \leq t \leq 1$.', '["$\\frac{39}{4}$", "$\\frac{43}{4}$", "$\\frac{35}{4}$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=3t^2$, so $\vec F(\vec r(t)) = (3 t^{3}, 6 t^{2})$ and $\vec r''(t) = (1, 6 t)$. Dotting and integrating from $0$ to $1$ gives $\frac{39}{4}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 1y)$ and $C$ is the path $\vec r(t) = (t, 3t^2)$ for $0 \leq t \leq 1$.', '["$\\frac{21}{4}$", "$\\frac{25}{4}$", "$\\frac{17}{4}$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=3t^2$, so $\vec F(\vec r(t)) = (3 t^{3}, 3 t^{2})$ and $\vec r''(t) = (1, 6 t)$. Dotting and integrating from $0$ to $1$ gives $\frac{21}{4}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 1y)$ and $C$ is the path $\vec r(t) = (t, 1t^2)$ for $0 \leq t \leq 1$.', '["$\\frac{3}{4}$", "$\\frac{7}{4}$", "$- \\frac{1}{4}$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=1t^2$, so $\vec F(\vec r(t)) = (t^{3}, t^{2})$ and $\vec r''(t) = (1, 2 t)$. Dotting and integrating from $0$ to $1$ gives $\frac{3}{4}$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 3y)$ and $C$ is the path $\vec r(t) = (t, 2t^2)$ for $0 \leq t \leq 2$.', '["$104$", "$105$", "$103$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=2t^2$, so $\vec F(\vec r(t)) = (2 t^{3}, 6 t^{2})$ and $\vec r''(t) = (1, 4 t)$. Dotting and integrating from $0$ to $2$ gives $104$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\displaystyle\int_C \vec F\cdot d\vec r$ where $\vec F = (xy, 2y)$ and $C$ is the path $\vec r(t) = (t, 2t^2)$ for $0 \leq t \leq 2$.', '["$72$", "$73$", "$71$", "$0$"]'::jsonb, 0, 'On $C$: $x=t, y=2t^2$, so $\vec F(\vec r(t)) = (2 t^{3}, 4 t^{2})$ and $\vec r''(t) = (1, 4 t)$. Dotting and integrating from $0$ to $2$ gives $72$.', 'Line Integrals', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A vector field $\vec F$ is called conservative on a domain $D$ if:', '["$\\vec F = \\nabla\\phi$ for some scalar potential function $\\phi$", "$\\nabla\\cdot\\vec F = 0$ throughout $D$", "$|\\vec F|$ is constant throughout $D$", "$\\vec F$ has no $z$-component"]'::jsonb, 0, 'A vector field is conservative when it is the gradient of some scalar potential function: $\vec F = \nabla\phi$.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The criterion for exactness (and path-independence) of a vector field $\vec F=(P,Q,R)$ with continuous partials on a simply connected domain is:', '["$\\nabla\\times\\vec F = \\vec 0$", "$\\nabla\\cdot\\vec F = 0$", "$\\nabla^2\\vec F = \\vec 0$", "$|\\vec F| = 1$"]'::jsonb, 0, 'On a simply connected domain, $\vec F$ is conservative (path-independent) iff it is irrotational: $\nabla\times\vec F = \vec 0$.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec F$ is conservative, so that $\vec F = \nabla\phi$ for a potential function $\phi$, how is the line integral $\int_C \vec F\cdot d\vec r$ from point $A$ to point $B$ evaluated?', '["$\\int_C \\vec F\\cdot d\\vec r = \\phi(B) - \\phi(A)$, independent of the path taken from $A$ to $B$", "It must always be computed via direct parametrization; no shortcut exists", "$\\int_C \\vec F\\cdot d\\vec r = \\phi(A) - \\phi(B)$", "It depends heavily on which path is chosen between $A$ and $B$"]'::jsonb, 0, 'The fundamental theorem for line integrals: when $\vec F=\nabla\phi$, $\int_C\vec F\cdot d\vec r = \phi(B)-\phi(A)$ for ANY path $C$ from $A$ to $B$ -- the integral depends only on the endpoints.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\vec F\cdot d\vec r$ is an exact differential $d\phi$ for some potential $\phi$, what is $\displaystyle\oint_C \vec F\cdot d\vec r$ around any closed loop $C$?', '["$0$ -- the line integral of a conservative field around any closed path is always zero", "Equal to the enclosed area", "Always positive", "Undefined for closed paths"]'::jsonb, 0, 'For a conservative field, $\oint_C \vec F\cdot d\vec r = \phi(A)-\phi(A) = 0$ for a closed loop starting and ending at the same point $A$.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is the planar vector field $\vec F = (2 x y){\vec i} + (x^{2}){\vec j}$ conservative? (Test whether $\partial Q/\partial x = \partial P/\partial y$.)', '["It IS conservative ($\\partial Q/\\partial x - \\partial P/\\partial y = 0$)", "It is NOT conservative", "Conservativeness cannot be tested without a third dimension", "Every planar vector field is automatically conservative"]'::jsonb, 0, '$\partial Q/\partial x = 2 x$ and $\partial P/\partial y = 2 x$, so $\partial Q/\partial x - \partial P/\partial y = 0$, which is zero, so $\vec F$ is conservative.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is the planar vector field $\vec F = (y^{2}){\vec i} + (2 x y){\vec j}$ conservative? (Test whether $\partial Q/\partial x = \partial P/\partial y$.)', '["It IS conservative ($\\partial Q/\\partial x - \\partial P/\\partial y = 0$)", "It is NOT conservative", "Conservativeness cannot be tested without a third dimension", "Every planar vector field is automatically conservative"]'::jsonb, 0, '$\partial Q/\partial x = 2 y$ and $\partial P/\partial y = 2 y$, so $\partial Q/\partial x - \partial P/\partial y = 0$, which is zero, so $\vec F$ is conservative.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is the planar vector field $\vec F = (x){\vec i} + (y){\vec j}$ conservative? (Test whether $\partial Q/\partial x = \partial P/\partial y$.)', '["It IS conservative ($\\partial Q/\\partial x - \\partial P/\\partial y = 0$)", "It is NOT conservative", "Conservativeness cannot be tested without a third dimension", "Every planar vector field is automatically conservative"]'::jsonb, 0, '$\partial Q/\partial x = 0$ and $\partial P/\partial y = 0$, so $\partial Q/\partial x - \partial P/\partial y = 0$, which is zero, so $\vec F$ is conservative.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is the planar vector field $\vec F = (y){\vec i} + (x^{2}){\vec j}$ conservative? (Test whether $\partial Q/\partial x = \partial P/\partial y$.)', '["It is NOT conservative ($\\partial Q/\\partial x - \\partial P/\\partial y = 2 x - 1$)", "It IS conservative", "Conservativeness cannot be tested without a third dimension", "Every planar vector field is automatically conservative"]'::jsonb, 0, '$\partial Q/\partial x = 2 x$ and $\partial P/\partial y = 1$, so $\partial Q/\partial x - \partial P/\partial y = 2 x - 1$, which is not zero, so $\vec F$ is not conservative.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is the planar vector field $\vec F = (2 x){\vec i} + (3 y){\vec j}$ conservative? (Test whether $\partial Q/\partial x = \partial P/\partial y$.)', '["It IS conservative ($\\partial Q/\\partial x - \\partial P/\\partial y = 0$)", "It is NOT conservative", "Conservativeness cannot be tested without a third dimension", "Every planar vector field is automatically conservative"]'::jsonb, 0, '$\partial Q/\partial x = 0$ and $\partial P/\partial y = 0$, so $\partial Q/\partial x - \partial P/\partial y = 0$, which is zero, so $\vec F$ is conservative.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is the planar vector field $\vec F = (x y){\vec i} + (x y){\vec j}$ conservative? (Test whether $\partial Q/\partial x = \partial P/\partial y$.)', '["It is NOT conservative ($\\partial Q/\\partial x - \\partial P/\\partial y = - x + y$)", "It IS conservative", "Conservativeness cannot be tested without a third dimension", "Every planar vector field is automatically conservative"]'::jsonb, 0, '$\partial Q/\partial x = y$ and $\partial P/\partial y = x$, so $\partial Q/\partial x - \partial P/\partial y = - x + y$, which is not zero, so $\vec F$ is not conservative.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the conservative field $\vec F = (y^{2}, 2 x y)$, find a potential function $\phi(x,y)$ such that $\vec F = \nabla\phi$.', '["$\\phi = x y^{2}$ (plus any constant)", "$\\phi = x y^{2} + x$", "$\\phi = 2 x y^{3}$", "$\\phi = - x y^{2}$"]'::jsonb, 0, 'Integrating $\phi_x = y^{2}$ with respect to $x$ and checking $\phi_y = 2 x y$ confirms $\phi = x y^{2}$ (up to an additive constant) works: $\phi_x=y^{2}$, $\phi_y=2 x y$.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the conservative field $\vec F = (2 x, 2 y)$, find a potential function $\phi(x,y)$ such that $\vec F = \nabla\phi$.', '["$\\phi = x^{2} + y^{2}$ (plus any constant)", "$\\phi = x^{2} + x + y^{2}$", "$\\phi = 4 x y$", "$\\phi = - x^{2} - y^{2}$"]'::jsonb, 0, 'Integrating $\phi_x = 2 x$ with respect to $x$ and checking $\phi_y = 2 y$ confirms $\phi = x^{2} + y^{2}$ (up to an additive constant) works: $\phi_x=2 x$, $\phi_y=2 y$.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the conservative field $\vec F = (y, x)$, find a potential function $\phi(x,y)$ such that $\vec F = \nabla\phi$.', '["$\\phi = x y$ (plus any constant)", "$\\phi = x y + x$", "$\\phi = x y$", "$\\phi = - x y$"]'::jsonb, 0, 'Integrating $\phi_x = y$ with respect to $x$ and checking $\phi_y = x$ confirms $\phi = x y$ (up to an additive constant) works: $\phi_x=y$, $\phi_y=x$.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the conservative field $\vec F = (3 x^{2}, -1)$, find a potential function $\phi(x,y)$ such that $\vec F = \nabla\phi$.', '["$\\phi = x^{3} - y$ (plus any constant)", "$\\phi = x^{3} + x - y$", "$\\phi = - 3 x^{2}$", "$\\phi = - x^{3} + y$"]'::jsonb, 0, 'Integrating $\phi_x = 3 x^{2}$ with respect to $x$ and checking $\phi_y = -1$ confirms $\phi = x^{3} - y$ (up to an additive constant) works: $\phi_x=3 x^{2}$, $\phi_y=-1$.', 'Line Integrals and Potential Functions', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The arc-length element $ds$ along a curve $\vec r(t) = (f(t), g(t), h(t))$ is given by:', '["$ds = |\\vec r''(t)|\\, dt = \\sqrt{f''(t)^2+g''(t)^2+h''(t)^2}\\, dt$", "$ds = f''(t)+g''(t)+h''(t)\\, dt$", "$ds = |\\vec r(t)|\\, dt$", "$ds = dt$, regardless of the curve''s shape"]'::jsonb, 0, 'The arc-length element is the speed times $dt$: $ds = |\vec r''(t)|\,dt$.', 'Line Integral w.r.t. Arc Length', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the arc length of the curve $\vec r(t) = (3t, 4t)$ for $0 \leq t \leq 2$.', '["$10$", "$11$", "$5$", "$2$"]'::jsonb, 0, 'Since $\vec r''(t) = (3,4)$ is constant, the speed is $|\vec r''(t)| = \sqrt{3^2+4^2} = 5$, and the arc length over $[0,2]$ is $\int_0^{2} 5\, dt = 10$.', 'Line Integral w.r.t. Arc Length', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the arc length of the curve $\vec r(t) = (4t, 2t)$ for $0 \leq t \leq 2$.', '["$4 \\sqrt{5}$", "$1 + 4 \\sqrt{5}$", "$2 \\sqrt{5}$", "$2$"]'::jsonb, 0, 'Since $\vec r''(t) = (4,2)$ is constant, the speed is $|\vec r''(t)| = \sqrt{4^2+2^2} = 2 \sqrt{5}$, and the arc length over $[0,2]$ is $\int_0^{2} 2 \sqrt{5}\, dt = 4 \sqrt{5}$.', 'Line Integral w.r.t. Arc Length', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the arc length of the curve $\vec r(t) = (2t, 1t)$ for $0 \leq t \leq 2$.', '["$2 \\sqrt{5}$", "$1 + 2 \\sqrt{5}$", "$\\sqrt{5}$", "$2$"]'::jsonb, 0, 'Since $\vec r''(t) = (2,1)$ is constant, the speed is $|\vec r''(t)| = \sqrt{2^2+1^2} = \sqrt{5}$, and the arc length over $[0,2]$ is $\int_0^{2} \sqrt{5}\, dt = 2 \sqrt{5}$.', 'Line Integral w.r.t. Arc Length', false, 'second', 2),
